window.ATLAS_BUNDLES=window.ATLAS_BUNDLES||{};window.ATLAS_BUNDLES["annotations-047"]={"VOPP1":{"hgnc":"HGNC:34518","symbol":"VOPP1","accessions":["Q96AW1"],"name":"WW domain binding protein VOPP1","length":"172","function":"Increases the transcriptional activity of NFKB1 by facilitating its nuclear translocation, DNA-binding and associated apoptotic response, when overexpressed (PubMed:15735698). May sequester WWOX in lysosomal vesicles and thereby regulate WWOX role as tumor suppressor (PubMed:30285739)","subunit":"Interacts with WWOX (via WW domain)","family":"Belongs to the VOPP1/ECOP family","domains":[],"function_pmids":["15735698","30285739"],"location":"Cytoplasmic vesicle membrane; Late endosome membrane; Lysosome membrane","shared_sequence_gene_count":"1","source_snapshot":"project UniProt records20261017/18","brief":"Increases the transcriptional activity of NFKB1 by facilitating its nuclear translocation, DNA-binding and associated apoptotic response, when overexpressed (PubMed:15735698). May sequester WWOX in lysosomal vesicles and thereby regulate WWOX role as tumor suppressor (PubMed:30285739)"},"VPS13D":{"hgnc":"HGNC:23595","symbol":"VPS13D","accessions":["Q5THJ4"],"name":"Intermembrane lipid transfer protein VPS13D","length":"4388","function":"Mediates the transfer of lipids between membranes at organelle contact sites (By similarity). Functions in promoting mitochondrial clearance by mitochondrial autophagy (mitophagy), also possibly by positively regulating mitochondrial fission (PubMed:29307555, PubMed:29604224). Mitophagy plays an important role in regulating cell health and mitochondrial size and homeostasis","subunit":"","family":"Belongs to the VPS13 family","domains":[],"function_pmids":["29307555","29604224"],"location":"","shared_sequence_gene_count":"1","source_snapshot":"project UniProt records20261017/18","brief":"Mediates the transfer of lipids between membranes at organelle contact sites (By similarity). Functions in promoting mitochondrial clearance by mitochondrial autophagy (mitophagy), also possibly by positively regulating mitochondrial fission (PubMed:29307555, PubMed:29604224). Mitophagy plays an important role in regulating cell health and mitochondrial size and homeostasis"},"VPS51":{"hgnc":"HGNC:1172","symbol":"VPS51","accessions":["Q9UID3"],"name":"Vacuolar protein sorting-associated protein 51 homolog","length":"782","function":"Acts as a component of the GARP complex that is involved in retrograde transport from early and late endosomes to the trans-Golgi network (TGN). The GARP complex is required for the maintenance of protein retrieval from endosomes to the TGN, acid hydrolase sorting, lysosome function, endosomal cholesterol traffic and autophagy. VPS51 participates in retrograde transport of acid hydrolase receptors, likely by promoting tethering and SNARE-dependent fusion of endosome-derived carriers to the TGN (PubMed:20685960). Acts as a component of the EARP complex that is involved in endocytic recycling. The EARP complex associates with Rab4-positive endosomes and promotes recycling of internalized transferrin receptor (TFRC) to the plasma membrane (PubMed:25799061)","subunit":"Component of the Golgi-associated retrograde protein (GARP) complex, also called VFT (VPS fifty-three) complex, composed of VPS51, VPS52, VPS53 and VPS54 (PubMed:20685960, PubMed:27440922, PubMed:30624672). Component of the endosome-associated retrograde protein (EARP) complex, composed of VPS51, VPS52, VPS53 and VPS50/Syndetin (PubMed:25799061, PubMed:27440922, PubMed:30624672). EIPR1 interacts with both EARP and GARP complexes and mediates the recruitment of the GARP complex to the trans-Golgi network (PubMed:27440922). Interacts with STX6 (via N-terminus) (PubMed:20685960). Interacts with VPS50 and VPS54 in an EIPR1-independent manner (PubMed:31721635)","family":"Belongs to the VPS51 family","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["20685960","25799061"],"location":"Golgi apparatus, trans-Golgi network；Recycling endosome","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"膜运输/高尔基/内吞；线粒体/代谢；黏附/受体/细胞表面；注释原文：Acts as a component of the GARP complex that is involved in retrograde transport from early and late endosomes to the trans-Golgi network (TGN).","function_evidence":"含实验支持条目；ECO:0000269","categories":"膜运输/高尔基/内吞；线粒体/代谢；黏附/受体/细胞表面"},"VPS9D1":{"hgnc":"HGNC:13526","symbol":"VPS9D1","accessions":["Q9Y2B5"],"name":"VPS9 domain-containing protein 1","length":"631","function":"未获得FUNCTION段；不等于没有已发表研究","subunit":"无可用SUBUNIT段","family":"","domains":"Domain 467-630: VPS9 [ECO:0000255/PROSITE-ProRule/PRU00550]","function_pmids":[],"location":"当前记录无定位注释","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"本次数据库无可用FUNCTION；只可据蛋白名称/结构域提出方向，不据此称全新功能。","function_evidence":"本次数据库无FUNCTION段；不等于无研究/无功能","categories":"未归类"},"VRK1":{"hgnc":"HGNC:12718","symbol":"VRK1","accessions":["Q99986"],"name":"Serine/threonine-protein kinase VRK1","length":"396","function":"Serine/threonine kinase involved in the regulation of key cellular processes including the cell cycle, nuclear condensation, transcription regulation, and DNA damage response (PubMed:14645249, PubMed:18617507, PubMed:19103756, PubMed:33076429). Controls chromatin organization and remodeling by mediating phosphorylation of histone H3 on 'Thr-4' and histone H2AX (H2aXT4ph) (PubMed:31527692, PubMed:37179361). It also phosphorylates KAT5 in response to DNA damage, promoting KAT5 association with chromatin and histone acetyltransferase activity (PubMed:33076429). Is involved in the regulation of cell cycle progression of neural progenitors, and is required for proper cortical neuronal migration (By similarity). Is involved in neurite elongation and branching in motor neurons, and has an essential role in Cajal bodies assembly, acting through COIL phosphorylation and the control of coilin degradation (PubMed:21920476, PubMed:31090908, PubMed:31527692). Involved in Golgi disassembly during the cell cycle: following phosphorylation by PLK3 during mitosis, it is required to induce Golgi fragmentation (PubMed:19103756). Phosphorylates BANF1: disrupts its ability to bind DNA, reduces its binding to LEM domain-containing proteins and causes its relocalization from the nucleus to the cytoplasm (PubMed:16495336). Phosphorylates TP53BP1 and p53/TP53 on 'Thr-18', preventing the interaction between p53/TP53 and MDM2 (PubMed:10951572, PubMed:31527692). Phosphorylates ATF2 which activates its transcriptional activity (PubMed:15105425). Phosphorylates JUN (PubMed:31527692)","subunit":"Interacts with HDAC1, KAT2B, SETDB1, KDM3A and KDM4A (PubMed:37179361). Associates with the nucleosome through interactions with nucleosome DNA, histone H2A and histone H2B; the interaction with H2A and H2B is mediated by the nucleosome acidic patch, a cluster of negatively charged residues of H2A and H2B forming a cleft within the nucleosome core (PubMed:35390161)\n(Microbial infection) Interacts with vaccinia protein B12; this interaction inhibits the repressive activity of the vaccinia virus B12 pseudokinase on viral replication factory formation","family":"Belongs to the protein kinase superfamily. CK1 Ser/Thr protein kinase family. VRK subfamily","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["10951572","14645249","15105425","16495336","18617507","19103756","21920476","31090908","31527692","33076429","37179361"],"location":"Nucleus；Cytoplasm；Nucleus, Cajal body","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"染色质/转录调控；DNA修复/复制；细胞周期/分裂；激酶/磷酸化信号；膜运输/高尔基/内吞；注释原文：Serine/threonine kinase involved in the regulation of key cellular processes including the cell cycle, nuclear condensation, transcription regulation, and DNA damage response (PubMed:14645249, PubMed:18617507, PubMed:19103756, PubMed:33076429).","function_evidence":"含实验支持条目；含同源推断，不能当该成员实测；ECO:0000250,ECO:0000269","categories":"染色质/转录调控；DNA修复/复制；细胞周期/分裂；激酶/磷酸化信号；膜运输/高尔基/内吞"},"VRK2":{"hgnc":"HGNC:12719","symbol":"VRK2","accessions":["Q86Y07"],"name":"Serine/threonine-protein kinase VRK2","length":"508","function":"Serine/threonine kinase that regulates several signal transduction pathways (PubMed:14645249, PubMed:16495336, PubMed:16704422, PubMed:17709393, PubMed:18286207, PubMed:18617507, PubMed:20679487). Isoform 1 modulates the stress response to hypoxia and cytokines, such as interleukin-1 beta (IL1B) and this is dependent on its interaction with MAPK8IP1, which assembles mitogen-activated protein kinase (MAPK) complexes (PubMed:17709393). Inhibition of signal transmission mediated by the assembly of MAPK8IP1-MAPK complexes reduces JNK phosphorylation and JUN-dependent transcription (PubMed:18286207). Phosphorylates 'Thr-18' of p53/TP53, histone H3, and may also phosphorylate MAPK8IP1 (PubMed:16704422). Phosphorylates BANF1 and disrupts its ability to bind DNA and reduces its binding to LEM domain-containing proteins (PubMed:16495336). Down-regulates the transactivation of transcription induced by ERBB2, HRAS, BRAF, and MEK1 (PubMed:20679487). Blocks the phosphorylation of ERK in response to ERBB2 and HRAS (PubMed:20679487). Can also phosphorylate the following substrates that are commonly used to establish in vitro kinase activity: casein, MBP and histone H2B, but it is not sure that this is physiologically relevant (PubMed:14645249)\nPhosphorylates 'Thr-18' of p53/TP53, as well as histone H3. Reduces p53/TP53 ubiquitination by MDM2, promotes p53/TP53 acetylation by EP300 and thereby increases p53/TP53 stability and activity","subunit":"Isoform 1 interacts with MAP3K7, MAP2K7, MAP2K1 and KSR1 (PubMed:17709393, PubMed:18286207, PubMed:20679487). Isoform 1 and isoform 2 interact with RAN and MAPK8IP1 (PubMed:18286207, PubMed:18617507)\n(Microbial infection) Isoform 1 interacts with Epstein-Barr virus BHRF1; this interaction is involved in protecting cells from apoptosis\n(Microbial infection) Isoform 1 interacts with vaccinia protein B12","family":"Belongs to the protein kinase superfamily. CK1 Ser/Thr protein kinase family. VRK subfamily","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["14645249","16495336","16704422","17709393","18286207","18617507","20679487"],"location":"Cytoplasm；Endoplasmic reticulum membrane；Single-pass type IV membrane protein；Mitochondrion membrane；Nucleus envelope；Nucleus","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"泛素化/蛋白稳态；染色质/转录调控；激酶/磷酸化信号；注释原文：Serine/threonine kinase that regulates several signal transduction pathways (PubMed:14645249, PubMed:16495336, PubMed:16704422, PubMed:17709393, PubMed:18286207, PubMed:18617507, PubMed:20679487).","function_evidence":"含实验支持条目；ECO:0000269","categories":"泛素化/蛋白稳态；染色质/转录调控；激酶/磷酸化信号"},"VRTN":{"hgnc":"HGNC:20223","symbol":"VRTN","accessions":["Q9H8Y1"],"name":"Vertnin","length":"702","function":"Acts as a transcription factor that regulates development of thoracic vertebrae","subunit":"","family":"Belongs to the vertnin family","domains":[],"function_pmids":[],"location":"Nucleus","shared_sequence_gene_count":"1","source_snapshot":"project UniProt records20261017/18","brief":"Acts as a transcription factor that regulates development of thoracic vertebrae"},"VSIG10L":{"hgnc":"HGNC:27111","symbol":"VSIG10L","accessions":["Q86VR7"],"name":"V-set and immunoglobulin domain-containing protein 10-like","length":"867","function":"未获得FUNCTION段；不等于没有已发表研究","subunit":"无可用SUBUNIT段","family":"","domains":"Domain 302-394: Ig-like C2-type 1\nDomain 402-487: Ig-like C2-type 2","function_pmids":[],"location":"Membrane; Single-pass type I membrane protein","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"本次数据库无可用FUNCTION；只可据蛋白名称/结构域提出方向，不据此称全新功能。","function_evidence":"本次数据库无FUNCTION段；不等于无研究/无功能","categories":"未归类"},"VSIG10L2":{"symbol":"VSIG10L2","accessions":["P0DP72"],"name":"V-set and immunoglobulin domain-containing protein 10-like 2","length":767,"function":"未获得FUNCTION段；不等于没有已发表研究","subunit":"无可用SUBUNIT段","domains":"Transmembrane: Helical [704–724]\nDomain: Ig-like 1 [34–140]\nDomain: Ig-like 2 [150–234]\nDomain: Ig-like 3 [242–324]\nDomain: Ig-like 4 [399–499]\nDomain: Ig-like 5 [501–593]\nDomain: Fibronectin type-III [599–699]","brief":"本次数据库无可用FUNCTION；只可据蛋白名称/结构域提出方向，不据此称全新功能。","function_evidence":"本次数据库无FUNCTION段；不等于无研究/无功能","categories":"未归类","location":"Membrane；Single-pass membrane protein","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020"},"VSIG2":{"symbol":"VSIG2","accessions":["Q96IQ7"],"name":"V-set and immunoglobulin domain-containing protein 2","length":327,"function":"未获得FUNCTION段；不等于没有已发表研究","subunit":"无可用SUBUNIT段","domains":"Transmembrane: Helical [244–264]\nDomain: Ig-like V-type [24–137]\nDomain: Ig-like C2-type [144–233]","brief":"本次数据库无可用FUNCTION；只可据蛋白名称/结构域提出方向，不据此称全新功能。","function_evidence":"本次数据库无FUNCTION段；不等于无研究/无功能","categories":"未归类","location":"Membrane；Single-pass type I membrane protein","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020"},"VSIG4":{"hgnc":"HGNC:17032","symbol":"VSIG4","accessions":["Q9Y279"],"name":"V-set and immunoglobulin domain-containing protein 4","length":"399","function":"Phagocytic receptor, strong negative regulator of T-cell proliferation and IL2 production. Potent inhibitor of the alternative complement pathway convertases","subunit":"无可用SUBUNIT段","family":"","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["17016562","17051150"],"location":"Membrane；Single-pass type I membrane protein","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"黏附/受体/细胞表面；注释原文：Phagocytic receptor, strong negative regulator of T-cell proliferation and IL2 production.","function_evidence":"含实验支持条目；ECO:0000269","categories":"黏附/受体/细胞表面"},"VSTM2A":{"hgnc":"HGNC:28499","symbol":"VSTM2A","accessions":["Q8TAG5"],"name":"V-set and transmembrane domain-containing protein 2A","length":"236","function":"Plays a role in the regulation of the early stage of white and brown preadipocyte cell differentiation. Promotes adipogenic commitment of preadipocytes by increasing gene expression of the transcription factor PPARG in a BMP4-dependent signaling pathway","subunit":"Homodimer","family":"","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["28052263"],"location":"Secreted","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"染色质/转录调控；发育/分化；注释原文：Plays a role in the regulation of the early stage of white and brown preadipocyte cell differentiation.","function_evidence":"含实验支持条目；ECO:0000269","categories":"染色质/转录调控；发育/分化"},"VTA1":{"hgnc":"HGNC:20954","symbol":"VTA1","accessions":["Q9NP79"],"name":"Vacuolar protein sorting-associated protein VTA1 homolog","length":"307","function":"Involved in the endosomal multivesicular bodies (MVB) pathway. MVBs contain intraluminal vesicles (ILVs) that are generated by invagination and scission from the limiting membrane of the endosome and mostly are delivered to lysosomes enabling degradation of membrane proteins, such as stimulated growth factor receptors, lysosomal enzymes and lipids. Thought to be a cofactor of VPS4A/B, which catalyzes disassembles membrane-associated ESCRT-III assemblies. Involved in the sorting and down-regulation of EGFR (By similarity). Involved in HIV-1 budding","subunit":"Interacts with VPS4B. Interacts with CHMP1B. Interacts with CHMP2A; the interaction probably involves the open conformation of (polymerized) CHMP2A. Interacts with CHMP3. Interacts with CHMP5; the interaction involves soluble CHMP5. Interacts with IST1","family":"Belongs to the VTA1 family","domains":[],"function_pmids":["15644320"],"location":"Cytoplasm; Endosome membrane","shared_sequence_gene_count":"1","source_snapshot":"project UniProt records20261017/18","brief":"Involved in the endosomal multivesicular bodies (MVB) pathway. MVBs contain intraluminal vesicles (ILVs) that are generated by invagination and scission from the limiting membrane of the endosome and mostly are delivered to lysosomes enabling degradation of membrane proteins, such as stimulated growth factor receptors, lysosomal enzymes and lipids. Thought to be a cofactor of VPS4A/B, which catalyzes disassembles membrane-associated ESCRT-III assemblies. Involved in the sorting and down-regulation of EGFR (By similarity). Involved in HIV-1 budding"},"VWA3B":{"hgnc":"HGNC:28385","symbol":"VWA3B","accessions":["Q502W6"],"name":"von Willebrand factor A domain-containing protein 3B","length":"1294","function":"未获得FUNCTION段；不等于没有已发表研究","subunit":"无可用SUBUNIT段","family":"","domains":"Domain 508-684: VWFA [ECO:0000255/PROSITE-ProRule/PRU00219]","function_pmids":[],"location":"Cytoplasm","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"本次数据库无可用FUNCTION；只可据蛋白名称/结构域提出方向，不据此称全新功能。","function_evidence":"本次数据库无FUNCTION段；不等于无研究/无功能","categories":"未归类"},"VWA5B2":{"hgnc":"HGNC:25144","symbol":"VWA5B2","accessions":["Q8N398"],"name":"von Willebrand factor A domain-containing protein 5B2","length":"1242","function":"未获得FUNCTION段；不等于没有已发表研究","subunit":"无可用SUBUNIT段","family":"","domains":"Domain 1-138: VIT [ECO:0000255/PROSITE-ProRule/PRU00801]\nDomain 354-527: VWFA","function_pmids":[],"location":"当前记录无定位注释","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"本次数据库无可用FUNCTION；只可据蛋白名称/结构域提出方向，不据此称全新功能。","function_evidence":"本次数据库无FUNCTION段；不等于无研究/无功能","categories":"未归类"},"VXN":{"hgnc":"HGNC:28498","symbol":"VXN","accessions":["Q8TAG6"],"name":"Vexin","length":"207","function":"Required for neurogenesis in the neural plate and retina. Strongly cooperates with neural bHLH factors to promote neurogenesis","subunit":"无可用SUBUNIT段","family":"Belongs to the vexin family","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":[],"location":"Cell membrane；Nucleus","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"发育/分化；注释原文：Required for neurogenesis in the neural plate and retina.","function_evidence":"含同源推断，不能当该成员实测；ECO:0000250","categories":"发育/分化"},"WAPL":{"hgnc":"HGNC:23293","symbol":"WAPL","accessions":["Q7Z5K2"],"name":"Wings apart-like protein homolog","length":"1190","function":"Regulator of sister chromatid cohesion in mitosis which negatively regulates cohesin association with chromatin (PubMed:26299517). Involved in both sister chromatid cohesion during interphase and sister-chromatid resolution during early stages of mitosis. Couples DNA replication to sister chromatid cohesion. Cohesion ensures that chromosome partitioning is accurate in both meiotic and mitotic cells and plays an important role in DNA repair","subunit":"Interacts with the cohesin complex throughout the cell cycle; interacts with both chromatin-bound and soluble pools of the complex. Interacts with RAD21; the interaction is direct. Interacts with PDS5A; the interaction is direct, cohesin-dependent and competitive with CDCA5/SORORIN. Interacts (via FGF motifs) with PDS5B; the interaction is direct. Interacts with a SMC1 protein (SMC1A or SMC1B) and SMC3\n(Microbial infection) Isoform 2 interacts with Epstein-Barr virus EBNA2","family":"Belongs to the WAPL family","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["15150110","17112726","17113138","19696148","19907496","21111234","23776203","26299517"],"location":"Nucleus；Chromosome；Cytoplasm","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"染色质/转录调控；DNA修复/复制；细胞周期/分裂；注释原文：Regulator of sister chromatid cohesion in mitosis which negatively regulates cohesin association with chromatin (PubMed:26299517).","function_evidence":"含实验支持条目；ECO:0000269","categories":"染色质/转录调控；DNA修复/复制；细胞周期/分裂"},"WASHC2A":{"hgnc":"HGNC:23416","symbol":"WASHC2A","accessions":["Q641Q2"],"name":"WASH complex subunit 2A","length":"1341","function":"Acts at least in part as component of the WASH core complex whose assembly at the surface of endosomes inhibits WASH nucleation-promoting factor (NPF) activity in recruiting and activating the Arp2/3 complex to induce actin polymerization and is involved in the fission of tubules that serve as transport intermediates during endosome sorting. Mediates the recruitment of the WASH core complex to endosome membranes via binding to phospholipids and VPS35 of the retromer CSC. Mediates the recruitment of the F-actin-capping protein dimer to the WASH core complex probably promoting localized F-actin polymerization needed for vesicle scission. Via its C-terminus binds various phospholipids, most strongly phosphatidylinositol 4-phosphate (PtdIns-(4)P), phosphatidylinositol 5-phosphate (PtdIns-(5)P) and phosphatidylinositol 3,5-bisphosphate (PtdIns-(3,5)P2). Involved in the endosome-to-plasma membrane trafficking and recycling of SNX27-retromer-dependent cargo proteins, such as GLUT1. Required for the association of DNAJC13, ENTR1, ANKRD50 with retromer CSC subunit VPS35. Required for the endosomal recruitment of CCC complex subunits COMMD1 and CCDC93 as well as the retriever complex subunit VPS35L","subunit":"Component of the WASH core complex also described as WASH regulatory complex (SHRC) composed of WASH (WASHC1, WASH2P or WASH3P), WASHC2 (WASHC2A or WASHC2C), WASHC3, WASHC4 and WASHC5; in the complex interacts (via N-terminus) directly with WASHC1. The WASH core complex associates with the F-actin-capping protein dimer (formed by CAPZA1, CAPZA2 or CAPZA3 and CAPZB) in a transient or substoichiometric manner which was initially described as WASH complex. Interacts with VPS35; mediates the association with the retromer CSC complex. Interacts with FKBP15. Interacts with CCDC93, CCDC22, VPS35L; indicative for an association of the WASH core complex with the CCC and retriever complexes (PubMed:25355947). Directly interacts with TBC1D23 (PubMed:29084197)","family":"Belongs to the FAM21 family","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["25355947","28892079"],"location":"Early endosome membrane；Cell membrane","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"膜运输/高尔基/内吞；细胞骨架/纤毛；线粒体/代谢；注释原文：Acts at least in part as component of the WASH core complex whose assembly at the surface of endosomes inhibits WASH nucleation-promoting factor (NPF) activity in recruiting and activating the Arp2/3 complex to induce actin polymerization and is involved in the fission of tubules that serve as transport intermediates during endosome sorting.","function_evidence":"含实验支持条目；ECO:0000269","categories":"膜运输/高尔基/内吞；细胞骨架/纤毛；线粒体/代谢"},"WASHC4":{"hgnc":"HGNC:29174","symbol":"WASHC4","accessions":["Q2M389"],"name":"WASH complex subunit 4","length":"1173","function":"Acts as a component of the WASH core complex that functions as a nucleation-promoting factor (NPF) at the surface of endosomes, where it recruits and activates the Arp2/3 complex to induce actin polymerization, playing a key role in the fission of tubules that serve as transport intermediates during endosome sorting","subunit":"Component of the WASH core complex also described as WASH regulatory complex (SHRC) composed of WASH (WASHC1, WASH2P or WASH3P), WASHC2 (WASHC2A or WASHC2C), WASHC3, WASHC4 and WASHC5. The WASH core complex associates via WASHC2 with the F-actin-capping protein dimer (formed by CAPZA1, CAPZA2 or CAPZA3 and CAPZB) in a transient or substoichiometric manner which was initially described as WASH complex","family":"Belongs to the SWIP family","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["19922875","20498093","21498477"],"location":"Early endosome","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"膜运输/高尔基/内吞；细胞骨架/纤毛；注释原文：Acts as a component of the WASH core complex that functions as a nucleation-promoting factor (NPF) at the surface of endosomes, where it recruits and activates the Arp2/3 complex to induce actin polymerization, playing a key role in the fission of tubules that serve as transport intermediates during endosome sorting","function_evidence":"含实验支持条目；ECO:0000269,ECO:0000303","categories":"膜运输/高尔基/内吞；细胞骨架/纤毛"},"WASHC5":{"hgnc":"HGNC:28984","symbol":"WASHC5","accessions":["Q12768"],"name":"WASH complex subunit 5","length":"1159","function":"Acts as a component of the WASH core complex that functions as a nucleation-promoting factor (NPF) at the surface of endosomes, where it recruits and activates the Arp2/3 complex to induce actin polymerization, playing a key role in the fission of tubules that serve as transport intermediates during endosome sorting (PubMed:19922875, PubMed:20498093). May be involved in axonal outgrowth. Involved in cellular localization of ADRB2 (PubMed:23085491). Involved in cellular trafficking of BLOC-1 complex cargos such as ATP7A and VAMP7 (PubMed:23676666)","subunit":"Component of the WASH core complex also described as WASH regulatory complex (SHRC) composed of WASH (WASHC1, WASH2P or WASH3P), WASHC2 (WASHC2A or WASHC2C), WASHC3, WASHC4 and WASHC5. The WASH core complex associates via WASHC2 with the F-actin-capping protein dimer (formed by CAPZA1, CAPZA2 or CAPZA3 and CAPZB) in a transient or substoichiometric manner which was initially described as WASH complex. Interacts with VCP, PI4K2A","family":"Belongs to the strumpellin family","domains":[],"function_pmids":["19922875","20833645","23085491","23676666"],"location":"Cytoplasm, cytosol; Endoplasmic reticulum; Early endosome","shared_sequence_gene_count":"1","source_snapshot":"project UniProt records20261017/18","brief":"Acts as a component of the WASH core complex that functions as a nucleation-promoting factor (NPF) at the surface of endosomes, where it recruits and activates the Arp2/3 complex to induce actin polymerization, playing a key role in the fission of tubules that serve as transport intermediates during endosome sorting (PubMed:19922875, PubMed:20498093). May be involved in axonal outgrowth. Involved in cellular localization of ADRB2 (PubMed:23085491). Involved in cellular trafficking of BLOC-1 complex cargos such as ATP7A and VAMP7 (PubMed:23676666)"},"WBP11":{"hgnc":"HGNC:16461","symbol":"WBP11","accessions":["Q9Y2W2"],"name":"WW domain-binding protein 11","length":"641","function":"Activates pre-mRNA splicing. May inhibit PP1 phosphatase activity","subunit":"Interacts with PPP1CA, PPP1CB and PPP1CC (By similarity). Interacts via the PGR motif with PQBP1 in the nucleus. Interacts with the WW domains of WBP4","family":"","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["10593949","11375989","14640981"],"location":"Nucleus；Cytoplasm","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"RNA加工/剪接；激酶/磷酸化信号；注释原文：Activates pre-mRNA splicing.","function_evidence":"含实验支持条目；ECO:0000269","categories":"RNA加工/剪接；激酶/磷酸化信号"},"WBP4":{"hgnc":"HGNC:12739","symbol":"WBP4","accessions":["O75554"],"name":"WW domain-binding protein 4","length":"376","function":"Involved in pre-mRNA splicing as a component of the spliceosome (PubMed:19592703, PubMed:28781166, PubMed:9724750). May play a role in cross-intron bridging of U1 and U2 snRNPs in the mammalian A complex (PubMed:9724750)","subunit":"Component of the spliceosome B complex (PubMed:28781166, PubMed:9724750). Associated with U2 snRNPs (PubMed:28781166, PubMed:9724750). Binds splicing factors SNRPB, SNRPC and SF1 (PubMed:9724750). Interacts via the WW domains with the Pro-rich domains of KHDRBS1/SAM68 (By similarity). Interacts via the WW domains with the Pro-rich domains of WBP11 (PubMed:19592703). Interacts with SNRNP200 (PubMed:35241646)","family":"","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["19592703","28781166","9724750"],"location":"Nucleus；Nucleus speckle","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"RNA加工/剪接；注释原文：Involved in pre-mRNA splicing as a component of the spliceosome (PubMed:19592703, PubMed:28781166, PubMed:9724750).","function_evidence":"含实验支持条目；ECO:0000269","categories":"RNA加工/剪接"},"WDCP":{"hgnc":"HGNC:26157","symbol":"WDCP","accessions":["Q9H6R7"],"name":"WD repeat and coiled-coil-containing protein","length":"721","function":"","subunit":"Oligomer. Interacts with HCK (via SH3 domain)","family":"","domains":[],"function_pmids":[],"location":"","shared_sequence_gene_count":"1","source_snapshot":"project UniProt records20261017/18","brief":""},"WDFY1":{"hgnc":"HGNC:20451","symbol":"WDFY1","accessions":["Q8IWB7"],"name":"WD repeat and FYVE domain-containing protein 1","length":"410","function":"Positively regulates TLR3- and TLR4-mediated signaling pathways by bridging the interaction between TLR3 or TLR4 and TICAM1. Promotes TLR3/4 ligand-induced activation of transcription factors IRF3 and NF-kappa-B, as well as the production of IFN-beta and inflammatory cytokines (PubMed:25736436)","subunit":"Binds PtdIns3P in vitro with high specificity over other phosphoinositides. Interacts (via WD repeat 2) with tyrosine-phosphorylated TLR3 (via TIR domain) in response to poly(I:C) (PubMed:25736436). Interacts with TICAM1 in response to poly(I:C) (By similarity). Interacts with TLR4 in response to LPS (By similarity)","family":"","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["25736436"],"location":"Early endosome","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"染色质/转录调控；免疫/炎症/细胞死亡；注释原文：Positively regulates TLR3- and TLR4-mediated signaling pathways by bridging the interaction between TLR3 or TLR4 and TICAM1.","function_evidence":"含实验支持条目；ECO:0000269","categories":"染色质/转录调控；免疫/炎症/细胞死亡"},"WDFY3":{"hgnc":"HGNC:20751","symbol":"WDFY3","accessions":["Q8IZQ1"],"name":"WD repeat and FYVE domain-containing protein 3","length":"3526","function":"Required for selective macroautophagy (aggrephagy). Acts as an adapter protein by linking specific proteins destined for degradation to the core autophagic machinery members, such as the ATG5-ATG12-ATG16L E3-like ligase, SQSTM1 and LC3 (PubMed:20417604). Along with p62/SQSTM1, involved in the formation and autophagic degradation of cytoplasmic ubiquitin-containing inclusions (p62 bodies, ALIS/aggresome-like induced structures). Along with SQSTM1, required to recruit ubiquitinated proteins to PML bodies in the nucleus (PubMed:20168092). Important for normal brain development. Essential for the formation of axonal tracts throughout the brain and spinal cord, including the formation of the major forebrain commissures. Involved in the ability of neural cells to respond to guidance cues. Required for cortical neurons to respond to the trophic effects of netrin-1/NTN1 (By similarity). Regulates Wnt signaling through the removal of DVL3 aggregates, likely in an autophagy-dependent manner. This process may be important for the determination of brain size during embryonic development (PubMed:27008544). May regulate osteoclastogenesis by acting on the TNFSF11/RANKL - TRAF6 pathway (By similarity). After cytokinetic abscission, involved in midbody remnant degradation (PubMed:24128730). In vitro strongly binds to phosphatidylinositol 3-phosphate (PtdIns3P) (PubMed:15292400)","subunit":"Directly interacts with ATG5 and associates with the ATG12-ATG5-ATG16L complex (PubMed:20417604). Interacts with p62/SQSTM1; this interaction is required to recruit WDFY3 to cytoplasmic bodies and to PML bodies (PubMed:20168092, PubMed:20971078). Directly interacts with GABARAP, GABARAPL1 and GABARAPL2; the interaction with GABARAP is required for WDFY3 recruitment to MAP1LC3B-positive p62/SQSTM1 bodies. Weakly interacts with MAP1LC3C; this interaction is direct. Does not interact with MAP1LC3A, nor MAP1LC3B (PubMed:24668264). Interacts with TRAF6 (By similarity)","family":"","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["15292400","20168092","20417604","24128730","27008544"],"location":"Nucleus membrane；Cytoplasm, cytosol；Nucleus, PML body；Membrane；Peripheral membrane protein；Cytoplasmic side；Perikaryon；Cell projection, axon","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"泛素化/蛋白稳态；发育/分化；注释原文：Required for selective macroautophagy (aggrephagy).","function_evidence":"含实验支持条目；含同源推断，不能当该成员实测；ECO:0000250,ECO:0000269","categories":"泛素化/蛋白稳态；发育/分化"},"WDHD1":{"hgnc":"HGNC:23170","symbol":"WDHD1","accessions":["O75717"],"name":"WD repeat and HMG-box DNA-binding protein 1","length":"1129","function":"Core replisome component that acts as a replication initiation factor. Binds directly to the CMG complex and functions as a hub to recruit additional proteins to the replication fork","subunit":"Trimer (PubMed:32453425, PubMed:34694004). Interacts with the polymerase alpha catalytic subunit POLA1. Interacts with MCM10 (PubMed:17761813). Interacts with DNA2 (PubMed:22570476). Interacts with CDC45 and GINS2 subunit of GINS complex; these interactions associate WDHD1 with the CMG helicase complex (PubMed:32453425, PubMed:34694004)","family":"","domains":[],"function_pmids":["19805216","34694004","35585232"],"location":"Nucleus, nucleoplasm","shared_sequence_gene_count":"1","source_snapshot":"project UniProt records20261017/18","brief":"Core replisome component that acts as a replication initiation factor. Binds directly to the CMG complex and functions as a hub to recruit additional proteins to the replication fork"},"WDR11":{"hgnc":"HGNC:13831","symbol":"WDR11","accessions":["Q9BZH6"],"name":"WD repeat-containing protein 11","length":"1224","function":"Involved in the Hedgehog (Hh) signaling pathway, is essential for normal ciliogenesis (PubMed:29263200). Regulates the proteolytic processing of GLI3 and cooperates with the transcription factor EMX1 in the induction of downstream Hh pathway gene expression and gonadotropin-releasing hormone production (PubMed:29263200). WDR11 complex facilitates the tethering of Adaptor protein-1 complex (AP-1)-derived vesicles. WDR11 complex acts together with TBC1D23 to facilitate the golgin-mediated capture of vesicles generated using AP-1 (PubMed:29426865)","subunit":"Component of the complex WDR11 composed of C17orf75, FAM91A1 and WDR11; FAM91A1 and WDR11 are required for proper location of the complex (PubMed:29426865). Interacts (via the N-terminal and the central portion of the protein) with EMX1 (PubMed:20887964). Interacts with GLI3; the interaction associateS EMX1 with GLI3 (PubMed:29263200). Interacts with TBC1D23; this interaction may be indirect and recruits TBC1D23 to AP-1-derived vesicles (PubMed:29084197, PubMed:29426865)","family":"","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["29263200","29426865"],"location":"Cytoplasm, cytoskeleton, cilium basal body；Cytoplasm；Nucleus；Cytoplasm, cytoskeleton, cilium axoneme；Cytoplasmic vesicle；Golgi apparatus, trans-Golgi network","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"染色质/转录调控；膜运输/高尔基/内吞；细胞骨架/纤毛；注释原文：Involved in the Hedgehog (Hh) signaling pathway, is essential for normal ciliogenesis (PubMed:29263200).","function_evidence":"含实验支持条目；ECO:0000269","categories":"染色质/转录调控；膜运输/高尔基/内吞；细胞骨架/纤毛"},"WDR12":{"hgnc":"HGNC:14098","symbol":"WDR12","accessions":["Q9GZL7"],"name":"Ribosome biogenesis protein WDR12","length":"423","function":"Component of the PeBoW complex, which is required for maturation of 28S and 5.8S ribosomal RNAs and formation of the 60S ribosome","subunit":"Component of the PeBoW complex, composed of BOP1, PES1 and WDR12 (PubMed:16043514, PubMed:16738141, PubMed:17189298, PubMed:17353269). The complex is held together by BOP1, which interacts with PES1 via its N-terminal domain and with WDR12 via a high-affinity interaction between the seven-bladed beta-propeller domains of the 2 proteins. The PeBoW complex associates with the 66S pre-ribosome (By similarity). Interacts (via UBL domain) with MDN1 (via VWFA/MIDAS domain) (PubMed:26601951)","family":"Belongs to the WD repeat WDR12/YTM1 family","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["16043514","17353269"],"location":"Nucleus, nucleolus；Nucleus, nucleoplasm","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"翻译/核糖体；注释原文：Component of the PeBoW complex, which is required for maturation of 28S and 5.8S ribosomal RNAs and formation of the 60S ribosome","function_evidence":"含实验支持条目；ECO:0000255,ECO:0000269","categories":"翻译/核糖体"},"WDR17":{"hgnc":"HGNC:16661","symbol":"WDR17","accessions":["Q8IZU2"],"name":"WD repeat-containing protein 17","length":"1322","function":"未获得FUNCTION段；不等于没有已发表研究","subunit":"无可用SUBUNIT段","family":"","domains":"Repeat 81-121: WD 1\nRepeat 123-164: WD 2\nRepeat 171-211: WD 3\nRepeat 221-261: WD 4\nRepeat 266-307: WD 5\nRepeat 391-431: WD 6\nRepeat 434-474: WD 7\nRepeat 478-518: WD 8\nRepeat 519-559: WD 9\nRepeat 564-604: WD 10\nRepeat 607-647: WD 11\nRepeat 650-690: WD 12","function_pmids":[],"location":"当前记录无定位注释","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"本次数据库无可用FUNCTION；只可据蛋白名称/结构域提出方向，不据此称全新功能。","function_evidence":"本次数据库无FUNCTION段；不等于无研究/无功能","categories":"未归类"},"WDR19":{"hgnc":"HGNC:18340","symbol":"WDR19","accessions":["Q8NEZ3"],"name":"WD repeat-containing protein 19","length":"1342","function":"As component of the IFT complex A (IFT-A), a complex required for retrograde ciliary transport and entry into cilia of G protein-coupled receptors (GPCRs), it is involved in cilia function and/or assembly (PubMed:20889716, PubMed:36775821). Essential for functional IFT-A assembly and ciliary entry of GPCRs (PubMed:20889716, PubMed:36775821). Associates with the BBSome complex to mediate ciliary transport (By similarity)","subunit":"Component of the IFT complex A (IFT-A) complex (PubMed:20889716, PubMed:27932497, PubMed:36775821). IFT-A complex is divided into a core subcomplex composed of IFT122:IFT140:WDR19 which is associated with TULP3 and a peripheral subcomplex composed of IFT43:WDR35:TTC21B (PubMed:27932497, PubMed:29220510). Interacts (via C-terminal region) with IFT122 (via C-terminal region) (PubMed:29220510). Interacts with BBS1 (By similarity). Interacts with TTC25 (PubMed:25860617)","family":"","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["20889716","36775821"],"location":"Cell projection, cilium；Cytoplasm, cytoskeleton, cilium basal body；Cell projection, cilium, photoreceptor outer segment；Cell projection, cilium, flagellum","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"细胞骨架/纤毛；黏附/受体/细胞表面；注释原文：As component of the IFT complex A (IFT-A), a complex required for retrograde ciliary transport and entry into cilia of G protein-coupled receptors (GPCRs), it is involved in cilia function and/or assembly (PubMed:20889716, PubMed:36775821).","function_evidence":"含实验支持条目；含同源推断，不能当该成员实测；ECO:0000250,ECO:0000269","categories":"细胞骨架/纤毛；黏附/受体/细胞表面"},"WDR20":{"hgnc":"HGNC:19667","symbol":"WDR20","accessions":["Q8TBZ3"],"name":"WD repeat-containing protein 20","length":"569","function":"Regulator of deubiquitinating complexes. Activates deubiquitinating activity of complexes containing USP12 (PubMed:20147737, PubMed:27373336). Anchors at the base of the ubiquitin-contacting loop of USP12 and remotely modulates the catalytic center of the enzyme (PubMed:27373336). Regulates shuttling of the USP12 deubiquitinase complex between the plasma membrane, cytoplasm and nucleus (PubMed:30466959)","subunit":"Interacts with USP12; promotes translocation of USP12/WDR20 to the plasma membrane (PubMed:20147737, PubMed:27373336, PubMed:30466959). Component of the USP12/WDR20/WDR48 deubiquitinating complex (PubMed:20147737, PubMed:27373336). Interacts with USP46; contributes to the cytoplasmic localization of the USP46/WDR20 complex (PubMed:20147737). Component of the USP12/DMWD/WDR48 deubiquitinating complex (PubMed:33844468)","family":"","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["20147737","27373336","30466959"],"location":"Cytoplasm；Nucleus","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"泛素化/蛋白稳态；注释原文：Regulator of deubiquitinating complexes.","function_evidence":"含实验支持条目；ECO:0000269","categories":"泛素化/蛋白稳态"},"WDR25":{"hgnc":"HGNC:21064","symbol":"WDR25","accessions":["Q64LD2"],"name":"WD repeat-containing protein 25","length":"544","function":"未获得FUNCTION段；不等于没有已发表研究","subunit":"无可用SUBUNIT段","family":"","domains":"Repeat 244-286: WD 1\nRepeat 290-329: WD 2\nRepeat 330-373: WD 3\nRepeat 375-420: WD 4\nRepeat 424-463: WD 5\nRepeat 469-510: WD 6\nRepeat 513-544: WD 7","function_pmids":[],"location":"当前记录无定位注释","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"本次数据库无可用FUNCTION；只可据蛋白名称/结构域提出方向，不据此称全新功能。","function_evidence":"本次数据库无FUNCTION段；不等于无研究/无功能","categories":"未归类"},"WDR26":{"hgnc":"HGNC:21208","symbol":"WDR26","accessions":["Q9H7D7"],"name":"WD repeat-containing protein 26","length":"661","function":"G-beta-like protein involved in cell signal transduction (PubMed:15378603, PubMed:19446606, PubMed:22065575, PubMed:23625927, PubMed:26895380, PubMed:27098453). Acts as a negative regulator in MAPK signaling pathway (PubMed:15378603). Functions as a scaffolding protein to promote G beta:gamma-mediated PLCB2 plasma membrane translocation and subsequent activation in leukocytes (PubMed:22065575, PubMed:23625927). Core component of the CTLH E3 ubiquitin-protein ligase complex that selectively accepts ubiquitin from UBE2H and mediates ubiquitination and subsequent proteasomal degradation of the transcription factor HBP1 (PubMed:29911972). Acts as a negative regulator of the canonical Wnt signaling pathway through preventing ubiquitination of beta-catenin CTNNB1 by the beta-catenin destruction complex, thus negatively regulating CTNNB1 degradation (PubMed:27098453). Serves as a scaffold to coordinate PI3K/AKT pathway-driven cell growth and migration (PubMed:26895380). Protects cells from oxidative stress-induced apoptosis via the down-regulation of AP-1 transcriptional activity as well as by inhibiting cytochrome c release from mitochondria (PubMed:19446606). Also protects cells by promoting hypoxia-mediated autophagy and mitophagy (By similarity)","subunit":"Forms homooligomers (PubMed:23625927). Identified in the CTLH complex that contains GID4, RANBP9 and/or RANBP10, MKLN1, MAEA, RMND5A (or alternatively its paralog RMND5B), GID8, ARMC8, WDR26 and YPEL5 (PubMed:29911972). Within this complex, MAEA, RMND5A (or alternatively its paralog RMND5B), GID8, WDR26, and RANBP9 and/or RANBP10 form the catalytic core, while GID4, MKLN1, ARMC8 and YPEL5 have ancillary roles (PubMed:29911972). Interacts with DDB1-CUL4A/B E3 ligase complexes (PubMed:17041588). Forms a complex composed of at least WDR26, a G-beta:gamma unit, and PLCB2 (PubMed:22065575, PubMed:23625927). Interacts with AXIN1 (PubMed:27098453)","family":"","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["15378603","19446606","23625927","26895380","27098453","29911972"],"location":"Cytoplasm；Nucleus；Mitochondrion","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"泛素化/蛋白稳态；染色质/转录调控；免疫/炎症/细胞死亡；线粒体/代谢；注释原文：G-beta-like protein involved in cell signal transduction (PubMed:15378603, PubMed:19446606, PubMed:22065575, PubMed:23625927, PubMed:26895380, PubMed:27098453).","function_evidence":"含实验支持条目；含同源推断，不能当该成员实测；ECO:0000250,ECO:0000269","categories":"泛素化/蛋白稳态；染色质/转录调控；免疫/炎症/细胞死亡；线粒体/代谢"},"WDR27":{"hgnc":"HGNC:21248","symbol":"WDR27","accessions":["A2RRH5"],"name":"WD repeat-containing protein 27","length":"827","function":"未获得FUNCTION段；不等于没有已发表研究","subunit":"无可用SUBUNIT段","family":"","domains":"Repeat 3-57: WD 1\nRepeat 62-101: WD 2\nRepeat 112-151: WD 3\nRepeat 155-194: WD 4\nRepeat 201-237: WD 5\nRepeat 292-337: WD 6\nRepeat 344-387: WD 7\nRepeat 502-542: WD 8\nRepeat 546-584: WD 9\nRepeat 590-629: WD 10\nRepeat 646-687: WD 11\nRepeat 698-740: WD 12\nRepeat 746-784: WD 13\nRepeat 788-826: WD 14","function_pmids":[],"location":"当前记录无定位注释","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"本次数据库无可用FUNCTION；只可据蛋白名称/结构域提出方向，不据此称全新功能。","function_evidence":"本次数据库无FUNCTION段；不等于无研究/无功能","categories":"未归类"},"WDR3":{"hgnc":"HGNC:12755","symbol":"WDR3","accessions":["Q9UNX4"],"name":"WD repeat-containing protein 3","length":"943","function":"Part of the small subunit (SSU) processome, first precursor of the small eukaryotic ribosomal subunit. During the assembly of the SSU processome in the nucleolus, many ribosome biogenesis factors, an RNA chaperone and ribosomal proteins associate with the nascent pre-rRNA and work in concert to generate RNA folding, modifications, rearrangements and cleavage as well as targeted degradation of pre-ribosomal RNA by the RNA exosome","subunit":"Part of the small subunit (SSU) processome, composed of more than 70 proteins and the RNA chaperone small nucleolar RNA (snoRNA) U3","family":"Belongs to the WD repeat WDR3/UTP12 family","domains":[],"function_pmids":["34516797"],"location":"Nucleus, nucleolus","shared_sequence_gene_count":"1","source_snapshot":"project UniProt records20261017/18","brief":"Part of the small subunit (SSU) processome, first precursor of the small eukaryotic ribosomal subunit. During the assembly of the SSU processome in the nucleolus, many ribosome biogenesis factors, an RNA chaperone and ribosomal proteins associate with the nascent pre-rRNA and work in concert to generate RNA folding, modifications, rearrangements and cleavage as well as targeted degradation of pre-ribosomal RNA by the RNA exosome"},"WDR31":{"hgnc":"HGNC:21421","symbol":"WDR31","accessions":["Q8NA23"],"name":"WD repeat-containing protein 31","length":"367","function":"未获得FUNCTION段；不等于没有已发表研究","subunit":"无可用SUBUNIT段","family":"","domains":"Repeat 53-90: WD 1\nRepeat 94-132: WD 2\nRepeat 137-175: WD 3\nRepeat 179-217: WD 4\nRepeat 221-264: WD 5\nRepeat 269-311: WD 6\nRepeat 315-353: WD 7","function_pmids":[],"location":"当前记录无定位注释","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"本次数据库无可用FUNCTION；只可据蛋白名称/结构域提出方向，不据此称全新功能。","function_evidence":"本次数据库无FUNCTION段；不等于无研究/无功能","categories":"未归类"},"WDR33":{"hgnc":"HGNC:25651","symbol":"WDR33","accessions":["Q9C0J8"],"name":"pre-mRNA 3' end processing protein WDR33","length":"1336","function":"Essential for both cleavage and polyadenylation of pre-mRNA 3' ends","subunit":"Component of the cleavage and polyadenylation specificity factor (CPSF) module of the pre-mRNA 3'-end processing complex. Interacts with CPSF3/CPSF73","family":"Belongs to the WD repeat WDR33 family","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["19217410"],"location":"Nucleus","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"RNA加工/剪接；注释原文：Essential for both cleavage and polyadenylation of pre-mRNA 3' ends","function_evidence":"含实验支持条目；ECO:0000269","categories":"RNA加工/剪接"},"WDR36":{"hgnc":"HGNC:30696","symbol":"WDR36","accessions":["Q8NI36"],"name":"WD repeat-containing protein 36","length":"895","function":"Part of the small subunit (SSU) processome, first precursor of the small eukaryotic ribosomal subunit. During the assembly of the SSU processome in the nucleolus, many ribosome biogenesis factors, an RNA chaperone and ribosomal proteins associate with the nascent pre-rRNA and work in concert to generate RNA folding, modifications, rearrangements and cleavage as well as targeted degradation of pre-ribosomal RNA by the RNA exosome. Involved in the nucleolar processing of SSU 18S rRNA (PubMed:21051332, PubMed:34516797). Involved in T-cell activation and highly coregulated with IL2 (PubMed:15177553)","subunit":"Part of the small subunit (SSU) processome, composed of more than 70 proteins and the RNA chaperone small nucleolar RNA (snoRNA) U3","family":"","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["15177553","21051332","34516797"],"location":"Nucleus, nucleolus","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"RNA加工/剪接；翻译/核糖体；注释原文：Part of the small subunit (SSU) processome, first precursor of the small eukaryotic ribosomal subunit.","function_evidence":"含实验支持条目；ECO:0000269","categories":"RNA加工/剪接；翻译/核糖体"},"WDR37":{"hgnc":"HGNC:31406","symbol":"WDR37","accessions":["Q9Y2I8"],"name":"WD repeat-containing protein 37","length":"494","function":"Required for normal ER Ca2+ handling in lymphocytes. Together with PACS1, it plays an essential role in stabilizing peripheral lymphocyte populations","subunit":"Forms homodimers (PubMed:34642815). Interacts with PACS1 (PubMed:34642815). Interacts with PACS2 (PubMed:34642815)","family":"","domains":[],"function_pmids":[],"location":"Cytoplasm; Nucleus","shared_sequence_gene_count":"1","source_snapshot":"project UniProt records20261017/18","brief":"Required for normal ER Ca2+ handling in lymphocytes. Together with PACS1, it plays an essential role in stabilizing peripheral lymphocyte populations"},"WDR4":{"hgnc":"HGNC:12756","symbol":"WDR4","accessions":["P57081"],"name":"tRNA (guanine-N(7)-)-methyltransferase non-catalytic subunit WDR4","length":"412","function":"Non-catalytic component of the METTL1-WDR4 methyltransferase complex required for the formation of N(7)-methylguanine in a subset of RNA species, such as tRNAs, mRNAs and microRNAs (miRNAs) (PubMed:12403464, PubMed:31031083, PubMed:31031084, PubMed:36599982, PubMed:36599985, PubMed:37369656). In the METTL1-WDR4 methyltransferase complex, WDR4 acts as a scaffold for tRNA-binding (PubMed:36599982, PubMed:36599985, PubMed:37369656). Required for the formation of N(7)-methylguanine at position 46 (m7G46) in a large subset of tRNAs that contain the 5'-RAGGU-3' motif within the variable loop (PubMed:12403464, PubMed:34352206, PubMed:34352207, PubMed:36599982, PubMed:36599985, PubMed:37369656). M7G46 interacts with C13-G22 in the D-loop to stabilize tRNA tertiary structure and protect tRNAs from decay (PubMed:36599982, PubMed:36599985). Also required for the formation of N(7)-methylguanine at internal sites in a subset of mRNAs (PubMed:31031084, PubMed:37379838). Also required for methylation of a specific subset of miRNAs, such as let-7 (PubMed:31031083). Independently of METTL1, also plays a role in genome stability: localizes at the DNA replication site and regulates endonucleolytic activities of FEN1 (PubMed:26751069)","subunit":"Non-catalytic component of the METTL1-WDR4 complex, composed of METTL1 and WDR4 (PubMed:12403464, PubMed:26751069, PubMed:36599982, PubMed:36599985, PubMed:37379838). Interacts with FEN1; the interaction is direct (PubMed:26751069)","family":"Belongs to the WD repeat TRM82 family","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["12403464","26751069","31031083","31031084","34352206","34352207","36599982","36599985","37369656","37379838"],"location":"Nucleus；Chromosome","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"DNA修复/复制；翻译/核糖体；注释原文：Non-catalytic component of the METTL1-WDR4 methyltransferase complex required for the formation of N(7)-methylguanine in a subset of RNA species, such as tRNAs, mRNAs and microRNAs (miRNAs) (PubMed:12403464, PubMed:31031083, PubMed:31031084, PubMed:36599982, PubMed:36599985, PubMed:37369656).","function_evidence":"含实验支持条目；ECO:0000269","categories":"DNA修复/复制；翻译/核糖体"},"WDR41":{"hgnc":"HGNC:25601","symbol":"WDR41","accessions":["Q9HAD4"],"name":"WD repeat-containing protein 41","length":"459","function":"Non-catalytic component of the C9orf72-SMCR8 complex, a complex that has guanine nucleotide exchange factor (GEF) activity and regulates autophagy (PubMed:27103069, PubMed:27193190, PubMed:27617292, PubMed:28195531). The C9orf72-SMCR8 complex promotes the exchange of GDP to GTP, converting inactive GDP-bound RAB8A and RAB39B into their active GTP-bound form, thereby promoting autophagosome maturation (PubMed:27103069). As part of the C9orf72-SMCR8 complex, stimulates RAB8A and RAB11A GTPase activity in vitro, however WDR42 is shown not be an essential complex component for this function (PubMed:32303654). The C9orf72-SMCR8 complex also acts as a negative regulator of autophagy initiation by interacting with the ULK1/ATG1 kinase complex and inhibiting its protein kinase activity (PubMed:27103069, PubMed:27617292)","subunit":"Component of the C9orf72-SMCR8 complex, at least composed of C9orf72, SMCR8 and WDR41 (PubMed:27103069, PubMed:27193190, PubMed:27617292, PubMed:28195531, PubMed:32303654). The complex is formed of two protomers, each individually consisting of one molecule each of C9orf72, SMCR8 and WDR41 (PubMed:32303654). The protomers homodimerize via an interaction between C9orf72 (via C-terminus) and SMCR8 (via N-terminus) (PubMed:32303654). Within each protomer SMCR8 (via DENN domain) acts as a bridging protein between WDR41 (via C-terminus and N-terminus) and C9orf72 (via C-terminus) (PubMed:32303654). The C9orf72-SMCR8 complex associates with the ULK1/ATG1 kinase complex (PubMed:27617292, PubMed:28195531)","family":"","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["27103069","27193190","27617292","28195531","32303654"],"location":"Cytoplasm","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"激酶/磷酸化信号；注释原文：Non-catalytic component of the C9orf72-SMCR8 complex, a complex that has guanine nucleotide exchange factor (GEF) activity and regulates autophagy (PubMed:27103069, PubMed:27193190, PubMed:27617292, PubMed:28195531).","function_evidence":"含实验支持条目；ECO:0000269","categories":"激酶/磷酸化信号"},"WDR43":{"hgnc":"HGNC:28945","symbol":"WDR43","accessions":["Q15061"],"name":"WD repeat-containing protein 43","length":"677","function":"Ribosome biogenesis factor that coordinates hyperactive transcription and ribogenesis (PubMed:17699751). Part of the small subunit (SSU) processome, first precursor of the small eukaryotic ribosomal subunit. During the assembly of the SSU processome in the nucleolus, many ribosome biogenesis factors, an RNA chaperone and ribosomal proteins associate with the nascent pre-rRNA and work in concert to generate RNA folding, modifications, rearrangements and cleavage as well as targeted degradation of pre-ribosomal RNA by the RNA exosome. Involved in nucleolar processing of pre-18S ribosomal RNA. Required for optimal pre-ribosomal RNA transcription by RNA polymerase I (PubMed:17699751, PubMed:34516797). Essential for stem cell pluripotency and embryonic development. In the nucleoplasm, recruited by promoter-associated/nascent transcripts and transcription to active promoters where it facilitates releases of elongation factor P-TEFb and paused RNA polymerase II to allow transcription elongation and maintain high-level expression of its targets genes (By similarity)","subunit":"Part of the small subunit (SSU) processome, composed of more than 70 proteins and the RNA chaperone small nucleolar RNA (snoRNA) U3 (PubMed:34516797). May be a component of the proposed t-UTP subcomplex of the ribosomal small subunit (SSU) processome containing at least UTP4, WDR43, HEATR1, UTP15, WDR75 (PubMed:17699751, PubMed:22916032). Binds to RNA; binding is required for its chromatin association. Interacts with CDK9, DDX21 and SUPT6H. Interacts with RNA polymerase II (By similarity). Interacts directly with UTP4 and UTP15 (PubMed:24219289)","family":"Belongs to the UTP5 family","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["17699751","34516797"],"location":"Nucleus, nucleolus；Nucleus, nucleolus fibrillar center；Nucleus, nucleoplasm","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"RNA加工/剪接；染色质/转录调控；翻译/核糖体；发育/分化；注释原文：Ribosome biogenesis factor that coordinates hyperactive transcription and ribogenesis (PubMed:17699751).","function_evidence":"含实验支持条目；含同源推断，不能当该成员实测；ECO:0000250,ECO:0000269","categories":"RNA加工/剪接；染色质/转录调控；翻译/核糖体；发育/分化"},"WDR45B":{"hgnc":"HGNC:25072","symbol":"WDR45B","accessions":["Q5MNZ6"],"name":"WD repeat domain phosphoinositide-interacting protein 3","length":"344","function":"Component of the autophagy machinery that controls the major intracellular degradation process by which cytoplasmic materials are packaged into autophagosomes and delivered to lysosomes for degradation (PubMed:28561066). Binds phosphatidylinositol 3-phosphate (PtdIns3P), and other phosphoinositides including PtdIns(3,5)P2, forming on membranes of the endoplasmic reticulum upon activation of the upstream ULK1 and PI3 kinases and is recruited at phagophore assembly sites where it regulates the elongation of nascent phagophores downstream of WIPI2 (PubMed:28561066, PubMed:30797857). In the cellular response to starvation, may also function together with the TSC1-TSC2 complex and RB1CC1 in the inhibition of the mTORC1 signaling pathway (PubMed:28503735)","subunit":"Interacts with the TSC1-TSC2 complex; stimulated upon starvation (PubMed:28561066). Interacts with RB1CC1 (PubMed:28561066). Interacts with ATG2A (PubMed:32483132)","family":"Belongs to the WD repeat PROPPIN family","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["28503735","28561066","30797857"],"location":"Preautophagosomal structure；Lysosome","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"激酶/磷酸化信号；注释原文：Component of the autophagy machinery that controls the major intracellular degradation process by which cytoplasmic materials are packaged into autophagosomes and delivered to lysosomes for degradation (PubMed:28561066).","function_evidence":"含实验支持条目；ECO:0000269","categories":"激酶/磷酸化信号"},"WDR46":{"hgnc":"HGNC:13923","symbol":"WDR46","accessions":["O15213"],"name":"WD repeat-containing protein 46","length":"610","function":"Scaffold component of the nucleolar structure. Required for localization of DDX21 and NCL to the granular compartment of the nucleolus (PubMed:23848194). Part of the small subunit (SSU) processome, first precursor of the small eukaryotic ribosomal subunit. During the assembly of the SSU processome in the nucleolus, many ribosome biogenesis factors, an RNA chaperone and ribosomal proteins associate with the nascent pre-rRNA and work in concert to generate RNA folding, modifications, rearrangements and cleavage as well as targeted degradation of pre-ribosomal RNA by the RNA exosome (PubMed:34516797)","subunit":"Part of the small subunit (SSU) processome, composed of more than 70 proteins and the RNA chaperone small nucleolar RNA (snoRNA) U3 (PubMed:34516797). Interacts with DDX21, NCL, NOP2 and EBNA1BP2 (PubMed:23848194)","family":"","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["23848194","34516797"],"location":"Nucleus, nucleolus","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"RNA加工/剪接；翻译/核糖体；注释原文：Scaffold component of the nucleolar structure.","function_evidence":"含实验支持条目；ECO:0000269","categories":"RNA加工/剪接；翻译/核糖体"},"WDR48":{"hgnc":"HGNC:30914","symbol":"WDR48","accessions":["Q8TAF3"],"name":"WD repeat-containing protein 48","length":"677","function":"Regulator of deubiquitinating complexes, which acts as a strong activator of USP1, USP12 and USP46 (PubMed:18082604, PubMed:19075014, PubMed:26388029, PubMed:31253762). Enhances the USP1-mediated deubiquitination of FANCD2; USP1 being almost inactive by itself (PubMed:18082604, PubMed:31253762). Activates deubiquitination by increasing the catalytic turnover without increasing the affinity of deubiquitinating enzymes for the substrate (PubMed:19075014, PubMed:27373336). Also activates deubiquitinating activity of complexes containing USP12 (PubMed:19075014, PubMed:27373336, PubMed:27650958). In complex with USP12, acts as a potential tumor suppressor by positively regulating PHLPP1 stability (PubMed:24145035). Docks at the distal end of the USP12 fingers domain and induces a cascade of structural changes leading to the activation of the enzyme (PubMed:27373336, PubMed:27650958). Together with RAD51AP1, promotes DNA repair by stimulating RAD51-mediated homologous recombination (PubMed:27239033, PubMed:27463890, PubMed:32350107). Binds single-stranded DNA (ssDNA) and double-stranded DNA (dsDNA) (PubMed:27239033, PubMed:31253762, PubMed:32350107). DNA-binding is required both for USP1-mediated deubiquitination of FANCD2 and stimulation of RAD51-mediated homologous recombination: both WDR48/UAF1 and RAD51AP1 have coordinated role in DNA-binding during these processes (PubMed:31253762, PubMed:32350107). Together with ATAD5 and by regulating USP1 activity, has a role in PCNA-mediated translesion synthesis (TLS) by deubiquitinating monoubiquitinated PCNA (PubMed:20147293). Together with ATAD5, has a role in recruiting RAD51 to stalled forks during replication stress (PubMed:31844045)\n(Microbial infection) In case of infection by Herpesvirus saimiri, may play a role in vesicular transport or membrane fusion events necessary for transport to lysosomes. Induces lysosomal vesicle formation via interaction with Herpesvirus saimiri tyrosine kinase-interacting protein (TIP). Subsequently, TIP recruits tyrosine-protein kinase LCK, resulting in down-regulation of T-cell antigen receptor TCR. May play a role in generation of enlarged endosomal vesicles via interaction with TIP (PubMed:12196293). In case of infection by papillomavirus HPV11, promotes the maintenance of the viral genome via its interaction with HPV11 helicase E1 (PubMed:18032488)","subunit":"Interacts with USP46 (PubMed:19075014, PubMed:26388029). Interacts with USP1 (PubMed:18082604, PubMed:26388029). Interacts with USP12 (PubMed:19075014, PubMed:27373336, PubMed:27650958). Component of the USP12-WDR20-WDR48 deubiquitinating complex (PubMed:27373336). Component of the USP12-DMWD-WDR48 deubiquitinating complex (PubMed:33844468). Interacts with PHLPP1 (PubMed:24145035). Interacts with RAD51AP1; the interaction is direct and promotes formation of a trimeric complex with RAD51 via RAD51AP1 (PubMed:27239033, PubMed:27463890). Interacts with ATAD5; the interaction regulates USP1-mediated PCNA deubiquitination (PubMed:20147293). Interacts with RAD51; the interaction is enhanced under replication stress (PubMed:31844045). Interacts with ITCH; the interaction is more efficient when both USP12 and WDR48/UAF1 are involved and may facilitate recruitment of the USP12 deubiquitinating complex to Notch (PubMed:22778262)\n(Microbial infection) Interacts with papillomavirus HPV11 E1 protein\n(Microbial infection) Interacts with Saimiriine herpesvirus TIP protein\n(Microbial infection) Interacts with human cytomegalovirus protein UL138\n(Microbial infection) Interacts with Epstein-Barr virus protein EBNA3","family":"Belongs to the WD repeat WDR48 family","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["12196293","18032488","18082604","19075014","20147293","24145035","26388029","27239033","27373336","27463890","27650958","31253762","31844045","32350107"],"location":"Nucleus；Cytoplasm；Lysosome；Late endosome","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"泛素化/蛋白稳态；DNA修复/复制；激酶/磷酸化信号；膜运输/高尔基/内吞；黏附/受体/细胞表面；注释原文：Regulator of deubiquitinating complexes, which acts as a strong activator of USP1, USP12 and USP46 (PubMed:18082604, PubMed:19075014, PubMed:26388029, PubMed:31253762).","function_evidence":"含实验支持条目；ECO:0000269","categories":"泛素化/蛋白稳态；DNA修复/复制；激酶/磷酸化信号；膜运输/高尔基/内吞；黏附/受体/细胞表面"},"WDR5":{"hgnc":"HGNC:12757","symbol":"WDR5","accessions":["P61964"],"name":"WD repeat-containing protein 5","length":"334","function":"Contributes to histone modification (PubMed:16600877, PubMed:16829960, PubMed:19103755, PubMed:19131338, PubMed:19556245, PubMed:20018852). May position the N-terminus of histone H3 for efficient trimethylation at 'Lys-4' (PubMed:16829960). As part of the MLL1/MLL complex it is involved in methylation and dimethylation at 'Lys-4' of histone H3 (PubMed:19556245). H3 'Lys-4' methylation represents a specific tag for epigenetic transcriptional activation (PubMed:18840606). As part of the NSL complex it may be involved in acetylation of nucleosomal histone H4 on several lysine residues (PubMed:19103755, PubMed:20018852). May regulate osteoblasts differentiation (By similarity). In association with RBBP5 and ASH2L, stimulates the histone methyltransferase activities of KMT2A, KMT2B, KMT2C, KMT2D, SETD1A and SETD1B (PubMed:21220120, PubMed:22266653)","subunit":"Interacts with PAXBP1; the interaction is direct and links a WDR5-containing histone methyltransferase complex to PAX7 and PAX3 (By similarity). Interacts with HCFC1 (PubMed:12670868). Component of the ATAC complex, a complex with histone acetyltransferase activity on histones H3 and H4 (PubMed:19103755). Component of the SET1 complex, at least composed of the catalytic subunit (SETD1A or SETD1B), WDR5, WDR82, RBBP5, ASH2L/ASH2, CXXC1/CFP1, HCFC1 and DPY30 (PubMed:16253997, PubMed:17355966, PubMed:17998332, PubMed:18838538). Core component of several methyltransferase-containing complexes including MLL1/MLL, MLL2/3 (also named ASCOM complex) and MLL4/WBP7 (PubMed:15199122, PubMed:15960975, PubMed:17021013, PubMed:17500065). Each complex is at least composed of ASH2L, RBBP5, WDR5, DPY30, one or more specific histone methyltransferases (KMT2A/MLL1, KMT2D/MLL2, KMT2C/MLL3 and KMT2B/MLL4), and the facultative components PAGR1, BACC1, CHD8, E2F6, HCFC1, HCFC2, HSP70, INO80C, KDM6A, KANSL1, LAS1L, MAX, MCRS1, MEN1, MGA, MYST1/MOF, NCOA6, PAXIP1/PTIP, PELP1, PHF20, PRP31, RING2, RUVB1/TIP49A, RUVB2/TIP49B, SENP3, TAF1, TAF4, TAF6, TAF7, TAF9, TEX10 and alpha- and beta-tubulin (PubMed:14992727, PubMed:18378692). Component of the NSL complex at least composed of MOF/KAT8, KANSL1, KANSL2, KANSL3, MCRS1, PHF20, OGT1/OGT, WDR5 and HCFC1 (PubMed:20018852). Interacts with KMT2A/MLL1 (via WIN motif) and RBBP5; the interaction is direct (PubMed:18829459, PubMed:18840606, PubMed:19556245, PubMed:21220120, PubMed:22266653, PubMed:22665483). Component of the ADA2A-containing complex (ATAC), composed of KAT14, KAT2A, TADA2L, TADA3L, ZZ3, MBIP, WDR5, YEATS2, CCDC101 and DR1 (PubMed:19103755). In the complex, it probably interacts directly with KAT2A, MBIP and KAT14 (PubMed:19103755). Interacts with histone H3 (PubMed:16600877, PubMed:16829959, PubMed:16829960, PubMed:16946699). Interacts with SETD1A (via WIN motif) (PubMed:17998332, PubMed:22266653, PubMed:22665483). Component of a histone methylation complex composed of at least ZNF335, RBBP5, ASH2L and WDR5; the complex may have histone H3-specific methyltransferase activity, however does not have specificity for 'Lys-4' of histone H3 (PubMed:19131338). Interacts with ZNF335 (PubMed:19131338, PubMed:23178126). Components of this complex may associate with components of the ZNF335-CCAR2-EMSY nuclear receptor-mediated transcription complex to form a complex at least composed of ZNF335, HCFC1, CCAR2, EMSY, MKI67, RBBP5, ASH2L and WDR5 (PubMed:19131338). Interacts with PER1 (By similarity). Interacts with KMT2B (via WIN motif), KMT2C (via WIN motif), KMT2D (via WIN motif) and SETD1B (via WIN motif) (PubMed:18840606, PubMed:22266653, PubMed:22665483)\n(Microbial infection) Interacts with herpes virus 8/HHV-8 protein LANA1; this interaction regulates the MLL1 histone methyltransferase activity on viral DNA","family":"Belongs to the WD repeat WDR5/wds family","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["16600877","16829960","18840606","19103755","19131338","19556245","20018852","21220120","22266653"],"location":"Nucleus","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"染色质/转录调控；发育/分化；注释原文：Contributes to histone modification (PubMed:16600877, PubMed:16829960, PubMed:19103755, PubMed:19131338, PubMed:19556245, PubMed:20018852).","function_evidence":"含实验支持条目；含同源推断，不能当该成员实测；ECO:0000250,ECO:0000269","categories":"染色质/转录调控；发育/分化"},"WDR54":{"hgnc":"HGNC:25770","symbol":"WDR54","accessions":["Q9H977"],"name":"WD repeat-containing protein 54","length":"334","function":"Plays a role in the adhesion and fusion of the sperm-oocyte membrane through its interactions with IZUMO1 and IZUMO1R/JUNO (By similarity). When cross-linked to form dimers and trimers, it has a regulatory effect on ERK signaling pathway activity in response to EGF stimulation. Colocalizes with the EGF receptor in WDR54-specific vesicle where it sustains the internalization and controls the degradation of the EGF receptor after EGF stimulation (PubMed:30458214)","subunit":"Homodimer and homotrimer; forms tight forms of dimers and trimers (PubMed:30458214). Interacts with IZUMO1 and IZUMO1R/JUNO (By similarity)","family":"","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["30458214"],"location":"Vesicle；Cytoplasm；Cell membrane","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"膜运输/高尔基/内吞；黏附/受体/细胞表面；注释原文：Plays a role in the adhesion and fusion of the sperm-oocyte membrane through its interactions with IZUMO1 and IZUMO1R/JUNO (By similarity).","function_evidence":"含实验支持条目；含同源推断，不能当该成员实测；ECO:0000250,ECO:0000269","categories":"膜运输/高尔基/内吞；黏附/受体/细胞表面"},"WDR55":{"hgnc":"HGNC:25971","symbol":"WDR55","accessions":["Q9H6Y2"],"name":"WD repeat-containing protein 55","length":"383","function":"Nucleolar protein that acts as a modulator of rRNA synthesis. Plays a central role during organogenesis (By similarity)","subunit":"无可用SUBUNIT段","family":"Belongs to the WD repeat WDR55 family","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":[],"location":"Nucleus, nucleolus；Cytoplasm","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"；注释原文：Nucleolar protein that acts as a modulator of rRNA synthesis.","function_evidence":"含同源推断，不能当该成员实测；ECO:0000250","categories":"未归类"},"WDR5B":{"hgnc":"HGNC:17826","symbol":"WDR5B","accessions":["Q86VZ2"],"name":"WD repeat-containing protein 5B","length":"330","function":"Plays a role in the proliferation of retinal pigment epithelial (RPE) cells (PubMed:39056772). May function as a substrate receptor for CUL4-DDB1 ubiquitin E3 ligase complex (By similarity)","subunit":"Probable part of a cullin-RING E3 protein ligase complex containing CUL4B-DDB1 and a substrate-recruiting component (DCAF). Interacts with CUL4B and DDB1","family":"Belongs to the WD repeat WDR5/wds family","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["39056772"],"location":"Nucleus","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"泛素化/蛋白稳态；黏附/受体/细胞表面；注释原文：Plays a role in the proliferation of retinal pigment epithelial (RPE) cells (PubMed:39056772).","function_evidence":"含实验支持条目；含同源推断，不能当该成员实测；ECO:0000250,ECO:0000269","categories":"泛素化/蛋白稳态；黏附/受体/细胞表面"},"WDR62":{"hgnc":"HGNC:24502","symbol":"WDR62","accessions":["O43379"],"name":"WD repeat-containing protein 62","length":"1518","function":"Required for cerebral cortical development. Plays a role in neuronal proliferation and migration (PubMed:20729831, PubMed:20890278). Plays a role in mother-centriole-dependent centriole duplication; the function also seems to involve CEP152, CDK5RAP2 and CEP63 through a stepwise assembled complex at the centrosome that recruits CDK2 required for centriole duplication (PubMed:26297806)","subunit":"Can form homodimers (via C-terminus) (PubMed:23341463). Interacts (via C-terminus) with MAPKBP1 (via C-terminus) (PubMed:23341463, PubMed:28089251). Interacts with CDK5RAP2, CEP152, CEP63 and KIAA0753 (PubMed:26297806). CEP63, CDK5RAP2, CEP152, WDR62 are proposed to form a stepwise assembled complex at the centrosome forming a ring near parental centrioles (PubMed:26297806)","family":"","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["20729831","20890278","26297806"],"location":"Nucleus；Cytoplasm, cytoskeleton, spindle pole；Cytoplasm, cytoskeleton, microtubule organizing center, centrosome；Cytoplasm, cytoskeleton, microtubule organizing center, centrosome, centriole","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"细胞骨架/纤毛；发育/分化；注释原文：Required for cerebral cortical development.","function_evidence":"含实验支持条目；ECO:0000269","categories":"细胞骨架/纤毛；发育/分化"},"WDR70":{"hgnc":"HGNC:25495","symbol":"WDR70","accessions":["Q9NW82"],"name":"WD repeat-containing protein 70","length":"654","function":"未获得FUNCTION段；不等于没有已发表研究","subunit":"无可用SUBUNIT段","family":"Belongs to the WD repeat GAD-1 family","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":[],"location":"当前记录无定位注释","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"本次数据库无可用FUNCTION；只可据蛋白名称/结构域提出方向，不据此称全新功能。","function_evidence":"本次数据库无FUNCTION段；不等于无研究/无功能","categories":"未归类"},"WDR74":{"hgnc":"HGNC:25529","symbol":"WDR74","accessions":["Q6RFH5"],"name":"WD repeat-containing protein 74","length":"385","function":"Regulatory protein of the MTREX-exosome complex involved in the synthesis of the 60S ribosomal subunit (PubMed:26456651). Participates in an early cleavage of the pre-rRNA processing pathway in cooperation with NVL (PubMed:29107693). Required for blastocyst formation, is necessary for RNA transcription, processing and/or stability during preimplantation development (By similarity)","subunit":"Isoform 1 interacts (through WDR repeats) with NVL; the interaction is independent of RNA or pre-60S ribosome particles. Isoform 2 does not interact with NVL (PubMed:28416111). Interacts with MTREX; the interaction dissociation in a late stage of rRNA synthesis is required for appropriate maturation of pre-60S particles and depends on the ATPase activity of NVL (PubMed:26456651, PubMed:29107693)","family":"","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["26456651","29107693"],"location":"Nucleus, nucleolus；Nucleus","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"RNA加工/剪接；染色质/转录调控；翻译/核糖体；发育/分化；注释原文：Regulatory protein of the MTREX-exosome complex involved in the synthesis of the 60S ribosomal subunit (PubMed:26456651).","function_evidence":"含实验支持条目；含同源推断，不能当该成员实测；ECO:0000250,ECO:0000269","categories":"RNA加工/剪接；染色质/转录调控；翻译/核糖体；发育/分化"},"WDR76":{"hgnc":"HGNC:25773","symbol":"WDR76","accessions":["Q9H967"],"name":"WD repeat-containing protein 76","length":"626","function":"Specifically binds 5-hydroxymethylcytosine (5hmC), suggesting that it acts as a specific reader of 5hmC","subunit":"Interacts with CUL4A and/or CUL4B","family":"Belongs to the WD repeat DDB2/WDR76 family","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":[],"location":"当前记录无定位注释","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"；注释原文：Specifically binds 5-hydroxymethylcytosine (5hmC), suggesting that it acts as a specific reader of 5hmC","function_evidence":"含同源推断，不能当该成员实测；ECO:0000250","categories":"未归类"},"WDR77":{"hgnc":"HGNC:29652","symbol":"WDR77","accessions":["Q9BQA1"],"name":"Methylosome protein WDR77","length":"342","function":"Non-catalytic component of the methylosome complex, composed of PRMT5, WDR77 and CLNS1A, which modifies specific arginines to dimethylarginines in several spliceosomal Sm proteins and histones (PubMed:11756452). This modification targets Sm proteins to the survival of motor neurons (SMN) complex for assembly into small nuclear ribonucleoprotein core particles. Might play a role in transcription regulation. The methylosome complex also methylates the Piwi proteins (PIWIL1, PIWIL2 and PIWIL4), methylation of Piwi proteins being required for the interaction with Tudor domain-containing proteins and subsequent localization to the meiotic nuage (PubMed:23071334)","subunit":"Component of the methylosome complex composed of PRMT5, WDR77 and CLNS1A (PubMed:18984161, PubMed:21081503). Found in a complex composed of PRMT5, WDR77 and RIOK1 (PubMed:21081503). RIOK1 and CLNS1A bound directly to PRMT5 at the same binding site, in a mutually exclusive manner, which allows the recruitment of distinct methylation substrates, such as nucleolin/NCL and Sm proteins, respectively (PubMed:21081503). Found in a complex with the component of the methylosome, PRMT5, CLNS1A, WDR77, PRMT1 and ERH (PubMed:25284789). Directly interacts with PRMT5, as well as with several Sm proteins, including SNRPB and SNRPD2 and, more weakly, SNRPD3 and SNRPE (PubMed:11756452, PubMed:33376131). Forms a compact hetero-octamer with PRMT5, decorating the outer surface of a PRMT5 tetramer. Interacts with SUZ12 and histone H2A/H2AC20, but not with histones H2B, H3 nor H4 (PubMed:16712789). Interacts with CTDP1 and LSM11 (PubMed:12560496, PubMed:16087681). Interacts with APEX1, AR and NKX3-1 (PubMed:12972618, PubMed:19188445). Interacts with CHTOP (PubMed:25284789). Interacts with FAM47E. Interacts with TSC22D2 (PubMed:27337956)","family":"","domains":[],"function_pmids":["11756452","23071334"],"location":"Nucleus; Cytoplasm","shared_sequence_gene_count":"1","source_snapshot":"project UniProt records20261017/18","brief":"Non-catalytic component of the methylosome complex, composed of PRMT5, WDR77 and CLNS1A, which modifies specific arginines to dimethylarginines in several spliceosomal Sm proteins and histones (PubMed:11756452). This modification targets Sm proteins to the survival of motor neurons (SMN) complex for assembly into small nuclear ribonucleoprotein core particles. Might play a role in transcription regulation. The methylosome complex also methylates the Piwi proteins (PIWIL1, PIWIL2 and PIWIL4), methylation of Piwi proteins being required for the interaction with Tudor domain-containing proteins and subsequent localization to the meiotic nuage (PubMed:23071334)"},"WDR81":{"hgnc":"HGNC:26600","symbol":"WDR81","accessions":["Q562E7"],"name":"WD repeat-containing protein 81","length":"1941","function":"Functions as a negative regulator of the PI3 kinase/PI3K activity associated with endosomal membranes via BECN1, a core subunit of the PI3K complex. By modifying the phosphatidylinositol 3-phosphate/PtdInsP3 content of endosomal membranes may regulate endosome fusion, recycling, sorting and early to late endosome transport (PubMed:26783301). It is for instance, required for the delivery of cargos like BST2/tetherin from early to late endosome and thereby participates indirectly to their degradation by the lysosome (PubMed:27126989). May also play a role in aggrephagy, the macroautophagic degradation of ubiquitinated protein aggregates. In this process, may regulate the interaction of SQSTM1 with ubiquitinated proteins and also recruit MAP1LC3C (PubMed:28404643). May also be involved in maintenance of normal mitochondrial structure and organization (By similarity)","subunit":"Interacts with WDR91; involved in early to late endosome cargo transport (PubMed:26783301, PubMed:27126989). Interacts with BECN1; negatively regulates the PI3 kinase/PI3K activity associated with endosomal membranes (PubMed:26783301). Interacts with SQSTM1; the interaction is direct and regulates the interaction of SQSTM1 with ubiquitinated proteins (PubMed:28404643). Interacts with MAP1LC3C; recruits MAP1LC3C to ubiquitinated protein aggregates in the aggrephagy process (PubMed:28404643)","family":"Belongs to the WD repeat WDR81 family","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["26783301","27126989","28404643"],"location":"Early endosome membrane；Peripheral membrane protein；Late endosome membrane；Lysosome membrane；Cytoplasmic vesicle, autophagosome membrane；Mitochondrion；Cytoplasm, cytosol","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"泛素化/蛋白稳态；激酶/磷酸化信号；膜运输/高尔基/内吞；线粒体/代谢；注释原文：Functions as a negative regulator of the PI3 kinase/PI3K activity associated with endosomal membranes via BECN1, a core subunit of the PI3K complex.","function_evidence":"含实验支持条目；含同源推断，不能当该成员实测；ECO:0000250,ECO:0000269","categories":"泛素化/蛋白稳态；激酶/磷酸化信号；膜运输/高尔基/内吞；线粒体/代谢"},"WDR82":{"hgnc":"HGNC:28826","symbol":"WDR82","accessions":["Q6UXN9"],"name":"WD repeat-containing protein 82","length":"313","function":"Regulatory component of the SET1/COMPASS complex implicated in the tethering of this complex to transcriptional start sites of active genes (PubMed:17998332, PubMed:18838538, PubMed:20516061). Facilitates histone H3 'Lys-4' methylation (H3K4me) via recruitment of the SETD1A or SETD1B to the 'Ser-5' phosphorylated C-terminal domain (CTD) of RNA polymerase II large subunit (POLR2A) (PubMed:17998332, PubMed:18838538). Component of the PNUTS-PP1 protein phosphatase complex, a protein phosphatase 1 (PP1) complex that promotes RNA polymerase II transcription pause-release, allowing transcription elongation (PubMed:39603240, PubMed:39603239). PNUTS-PP1 also plays a role in the control of chromatin structure and cell cycle progression during the transition from mitosis into interphase (PubMed:20516061). Together with ZC3H4, but independently of the SET1 complex, part of a transcription termination checkpoint that promotes transcription termination of long non-coding RNAs (lncRNAs) (PubMed:33767452, PubMed:33913806). The transcription termination checkpoint is activated by the inefficiently spliced first exon of lncRNAs and promotes transcription termination of lncRNAs and their subsequent degradation by the exosome (PubMed:33767452)","subunit":"Component of the SET1/COMPASS complex, at least composed of the catalytic subunit (SETD1A or SETD1B), WDR5, WDR82, RBBP5, ASH2L/ASH2, CXXC1/CFP1, HCFC1 and DPY30 (PubMed:16253997, PubMed:17355966, PubMed:17998332, PubMed:18838538). Component of the PNUTS-PP1 phosphatase complex, composed of PPP1R10/PNUTS, TOX4, WDR82, and PPP1CA or PPP1CB or PPP1CC (PubMed:20516061, PubMed:39603240, PubMed:39603239). Associated with multiple protein complexes including an RNA polymerase II complex, MLL3/MLL4 complex and a chaperonin-containing TCP1 complex (PubMed:20516061). Interacts with SETD1B (via N-terminal region); the interaction is direct (PubMed:17998332, PubMed:37030068). Interacts with SETD1A (via N-terminal region); the interaction is direct (PubMed:17998332, PubMed:37030068). Interacts with CUL4B (PubMed:17041588). Interacts with RBBP5 (PubMed:18838538). Interacts with POLR2B (PubMed:17998332). Interacts with hyperphosphorylated C-terminal domain (CTD) of RNA polymerase II large subunit (POLR2A) (PubMed:17998332). Binds specifically to CTD heptad repeats phosphorylated on 'Ser-5' of each heptad (PubMed:17998332). SETD1A enhances its interaction with POLR2A (PubMed:17998332). Interacts with PPP1R10/PNUTS (PubMed:20516061). Interacts with PPP1CA in the presence of PPP1R10/PNUTS (PubMed:20516061). Interacts with ZC3H4; interaction is independent of the SET1 complex and promotes transcription termination of long non-coding RNAs (lncRNAs) (PubMed:33913806)","family":"Belongs to the WD repeat SWD2 family","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["17998332","18838538","20516061","33767452","33913806","39603239","39603240"],"location":"Nucleus；Chromosome；Cytoplasm","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"RNA加工/剪接；染色质/转录调控；细胞周期/分裂；激酶/磷酸化信号；注释原文：Regulatory component of the SET1/COMPASS complex implicated in the tethering of this complex to transcriptional start sites of active genes (PubMed:17998332, PubMed:18838538, PubMed:20516061).","function_evidence":"含实验支持条目；ECO:0000269","categories":"RNA加工/剪接；染色质/转录调控；细胞周期/分裂；激酶/磷酸化信号"},"WDR83":{"hgnc":"HGNC:32672","symbol":"WDR83","accessions":["Q9BRX9"],"name":"WD repeat domain-containing protein 83","length":"315","function":"Molecular scaffold protein for various multimeric protein complexes. Acts as a module in the assembly of a multicomponent scaffold for the ERK pathway, linking ERK responses to specific agonists. At low concentrations it enhances ERK activation, whereas high concentrations lead to the inhibition of ERK activation. Also involved in response to hypoxia by acting as a negative regulator of HIF1A/HIF-1-alpha via its interaction with EGLN3/PHD3. May promote degradation of HIF1A. May act by recruiting signaling complexes to a specific upstream activator (By similarity). May also be involved in pre-mRNA splicing. Participates in tight junction development by regulating apico-basal polarity, a key step in tissue development and organization. Mechanistically, regulates the translocation of PAR6-aPKC from the cytoplasm to the apical surface by acting as an adapter between PARD6B AND CRB3 (PubMed:23439680). Also acts as a negative regulator of mTORC1 under nutrient-rich conditions by binding to the active Rag GTPases to inhibit mTORC1 localization to the lysosome and phosphorylation of downstream targets. This facilitates constitutive basal autophagy during nutrient availability (PubMed:38103557)","subunit":"Interacts with EGLN3/PHD3. Interacts with ERK signaling proteins MAP2K1/MEK1, MAP2K2/MEK2, LAMTOR3, ARAF/Raf-1, MAPK1/ERK2 and MAPK3/ERK1 (By similarity). Identified in the spliceosome C complex. Interacts with PARD6B and CRB3 (PubMed:23439680). Interacts strongly with GTP-bound RRAGA but not with inactive GDP-bound (PubMed:38103557). Interacts with p62/SQSTM1 (PubMed:38103557)","family":"Belongs to the WD repeat MORG1 family","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["23439680","38103557"],"location":"Cytoplasm；Lysosome；Nucleus","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"RNA加工/剪接；激酶/磷酸化信号；发育/分化；注释原文：Molecular scaffold protein for various multimeric protein complexes.","function_evidence":"含实验支持条目；含同源推断，不能当该成员实测；ECO:0000250,ECO:0000269","categories":"RNA加工/剪接；激酶/磷酸化信号；发育/分化"},"WDR86":{"hgnc":"HGNC:28020","symbol":"WDR86","accessions":["Q86TI4"],"name":"WD repeat-containing protein 86","length":"376","function":"","subunit":"","family":"","domains":[],"function_pmids":[],"location":"","shared_sequence_gene_count":"1","source_snapshot":"project UniProt records20261017/18","brief":""},"WDR88":{"hgnc":"HGNC:26999","symbol":"WDR88","accessions":["Q6ZMY6"],"name":"WD repeat-containing protein 88","length":"472","function":"未获得FUNCTION段；不等于没有已发表研究","subunit":"无可用SUBUNIT段","family":"","domains":"Repeat 100-139: WD 1\nRepeat 143-182: WD 2\nRepeat 184-224: WD 3\nRepeat 228-267: WD 4\nRepeat 271-310: WD 5\nRepeat 319-358: WD 6\nRepeat 361-400: WD 7","function_pmids":[],"location":"当前记录无定位注释","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"本次数据库无可用FUNCTION；只可据蛋白名称/结构域提出方向，不据此称全新功能。","function_evidence":"本次数据库无FUNCTION段；不等于无研究/无功能","categories":"未归类"},"WDSUB1":{"hgnc":"HGNC:26697","symbol":"WDSUB1","accessions":["Q8N9V3"],"name":"WD repeat, SAM and U-box domain-containing protein 1","length":"476","function":"未获得FUNCTION段；不等于没有已发表研究","subunit":"无可用SUBUNIT段","family":"","domains":"Repeat 10-47: WD 1\nRepeat 52-91: WD 2\nRepeat 95-134: WD 3\nRepeat 137-176: WD 4\nRepeat 178-228: WD 5\nRepeat 237-276: WD 6\nRepeat 279-318: WD 7\nDomain 332-396: SAM [ECO:0000255/PROSITE-ProRule/PRU00184]\nDomain 403-476: U-box","function_pmids":[],"location":"当前记录无定位注释","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"本次数据库无可用FUNCTION；只可据蛋白名称/结构域提出方向，不据此称全新功能。","function_evidence":"本次数据库无FUNCTION段；不等于无研究/无功能","categories":"未归类"},"WDTC1":{"hgnc":"HGNC:29175","symbol":"WDTC1","accessions":["Q8N5D0"],"name":"WD and tetratricopeptide repeats protein 1","length":"677","function":"May function as a substrate receptor for CUL4-DDB1 E3 ubiquitin-protein ligase complex","subunit":"无可用SUBUNIT段","family":"","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["16964240"],"location":"当前记录无定位注释","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"泛素化/蛋白稳态；黏附/受体/细胞表面；注释原文：May function as a substrate receptor for CUL4-DDB1 E3 ubiquitin-protein ligase complex","function_evidence":"含实验支持条目；ECO:0000269","categories":"泛素化/蛋白稳态；黏附/受体/细胞表面"},"WEE1":{"hgnc":"HGNC:12761","symbol":"WEE1","accessions":["P30291"],"name":"Wee1-like protein kinase","length":"646","function":"Acts as a negative regulator of entry into mitosis (G2 to M transition) by protecting the nucleus from cytoplasmically activated cyclin B1-complexed CDK1 before the onset of mitosis by mediating phosphorylation of CDK1 on 'Tyr-15' (PubMed:15070733, PubMed:7743995, PubMed:8348613, PubMed:8428596). Specifically phosphorylates and inactivates cyclin B1-complexed CDK1 reaching a maximum during G2 phase and a minimum as cells enter M phase (PubMed:7743995, PubMed:8348613, PubMed:8428596). Phosphorylation of cyclin B1-CDK1 occurs exclusively on 'Tyr-15' and phosphorylation of monomeric CDK1 does not occur (PubMed:7743995, PubMed:8348613, PubMed:8428596). Its activity increases during S and G2 phases and decreases at M phase when it is hyperphosphorylated (PubMed:7743995). A correlated decrease in protein level occurs at M/G1 phase, probably due to its degradation (PubMed:7743995)","subunit":"","family":"Belongs to the protein kinase superfamily. Ser/Thr protein kinase family. WEE1 subfamily","domains":[],"function_pmids":["15070733","7743995","8348613","8428596"],"location":"Nucleus","shared_sequence_gene_count":"1","source_snapshot":"project UniProt records20261017/18","brief":"Acts as a negative regulator of entry into mitosis (G2 to M transition) by protecting the nucleus from cytoplasmically activated cyclin B1-complexed CDK1 before the onset of mitosis by mediating phosphorylation of CDK1 on 'Tyr-15' (PubMed:15070733, PubMed:7743995, PubMed:8348613, PubMed:8428596). Specifically phosphorylates and inactivates cyclin B1-complexed CDK1 reaching a maximum during G2 phase and a minimum as cells enter M phase (PubMed:7743995, PubMed:8348613, PubMed:8428596). Phosphorylation of cyclin B1-CDK1 occurs exclusively on 'Tyr-15' and phosphorylation of monomeric CDK1 does not occur (PubMed:7743995, PubMed:8348613, PubMed:8428596). Its activity increases during S and G2 phases and decreases at M phase when it is hyperphosphorylated (PubMed:7743995). A correlated decrease in protein level occurs at M/G1 phase, probably due to its degradation (PubMed:7743995)"},"WHR1":{"hgnc":"HGNC:11398","symbol":"WHR1","accessions":["P49842"],"name":"Winged helix repair factor 1","length":"254","function":"DNA-binding protein which is required for efficient transcription-coupled nucleotide excision repair (TC-NER) (PubMed:38252411, PubMed:38890355, PubMed:39353615, PubMed:39547223, PubMed:39547228, PubMed:39547229). Acts as part of a TC-NER complex which assembles and interacts with RNA polymerase II (RNAPII) when it stalls at DNA lesions (PubMed:39547223, PubMed:39547228, PubMed:39547229). TC-NER complex subunit UVSSA binds to the GTF2H1/p62 subunit of the TFIIH transcription factor complex, tethering TFIIH to the TC-NER complex (PubMed:39547228). WHR1/STK19 then interacts with the XPD helicase subunit of TFIIH which guides TFIIH to DNA downstream of the stalled RNAPII, ensuring DNA repair (PubMed:39353615, PubMed:39547228, PubMed:39547229). Directly interacts with RNAPII and also binds to downstream DNA (PubMed:39547229). Promotes the timely removal of DNA damage-stalled RNAPII, allowing downstream NER factors to access DNA lesions (PubMed:39547228, PubMed:39547229). Required for monoubiquitination of UVSSA (PubMed:39353615). Regulates repositioning and stabilization of UVSSA within the TC-NER complex (PubMed:39547223). Stimulates ubiquitination of RNAPII complex member RBP1 (PubMed:39547223). Also binds to RNA and regulates the expression levels of many mRNAs (PubMed:38252411, PubMed:38890355)","subunit":"Monomer in solution (PubMed:38890355). Homodimer; when bound to DNA (PubMed:38252411). Component of a transcription-coupled nucleotide excision repair (TC-NER) complex composed of STK19, ERCC6, ERCC8, DDA1, DDB1, ELOF1 and UVSSA which assembles and interacts with the multiprotein RNA polymerase II complex when it stalls at DNA lesions (PubMed:39547223, PubMed:39547228, PubMed:39547229)","family":"Belongs to the STK19 family","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["38252411","38890355","39353615","39547223","39547228","39547229"],"location":"Nucleus；Cytoplasm","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"泛素化/蛋白稳态；染色质/转录调控；DNA修复/复制；注释原文：DNA-binding protein which is required for efficient transcription-coupled nucleotide excision repair (TC-NER) (PubMed:38252411, PubMed:38890355, PubMed:39353615, PubMed:39547223, PubMed:39547228, PubMed:39547229).","function_evidence":"含实验支持条目；ECO:0000269","categories":"泛素化/蛋白稳态；染色质/转录调控；DNA修复/复制"},"WIZ":{"hgnc":"HGNC:30917","symbol":"WIZ","accessions":["O95785"],"name":"Protein Wiz","length":"1651","function":"May link EHMT1 and EHMT2 histone methyltransferases to the CTBP corepressor machinery. May be involved in EHMT1-EHMT2 heterodimer formation and stabilization (By similarity)","subunit":"Interacts with EHMT1, EHMT2, CTBP1 and CTBP2 (By similarity). Part of a complex containing at least CDYL, REST, WIZ, SETB1, EHMT1 and EHMT2","family":"Belongs to the krueppel C2H2-type zinc-finger protein family","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":[],"location":"Nucleus","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"染色质/转录调控；注释原文：May link EHMT1 and EHMT2 histone methyltransferases to the CTBP corepressor machinery.","function_evidence":"含同源推断，不能当该成员实测；ECO:0000250","categories":"染色质/转录调控"},"WNK1":{"hgnc":"HGNC:14540","symbol":"WNK1","accessions":["Q9H4A3"],"name":"Serine/threonine-protein kinase WNK1","length":"2382","function":"Serine/threonine-protein kinase component of the WNK1-SPAK/OSR1 kinase cascade, which acts as a key regulator of blood pressure and regulatory volume increase by promoting ion influx (PubMed:15883153, PubMed:17190791, PubMed:31656913, PubMed:34289367, PubMed:36318922). WNK1 mediates regulatory volume increase in response to hyperosmotic stress by acting as a molecular crowding sensor, which senses cell shrinkage and mediates formation of a membraneless compartment by undergoing liquid-liquid phase separation (PubMed:36318922). The membraneless compartment concentrates WNK1 with its substrates, OXSR1/OSR1 and STK39/SPAK, promoting WNK1-dependent phosphorylation and activation of downstream kinases OXSR1/OSR1 and STK39/SPAK (PubMed:15883153, PubMed:16263722, PubMed:17190791, PubMed:19739668, PubMed:21321328, PubMed:22989884, PubMed:25477473, PubMed:34289367, PubMed:36318922). Following activation, OXSR1/OSR1 and STK39/SPAK catalyze phosphorylation of ion cotransporters SLC12A1/NKCC2, SLC12A2/NKCC1, SLC12A5/KCC2 and SLC12A6/KCC3, regulating their activity (PubMed:16263722, PubMed:21321328). Phosphorylation of Na-K-Cl cotransporters SLC12A2/NKCC1 and SLC12A2/NKCC1 promote their activation and ion influx; simultaneously, phosphorylation of K-Cl cotransporters SLC12A5/KCC2 and SLC12A6/KCC3 inhibit their activity, blocking ion efflux (PubMed:19665974, PubMed:21321328). Also acts as a regulator of angiogenesis in endothelial cells via activation of OXSR1/OSR1 and STK39/SPAK: activation of OXSR1/OSR1 regulates chemotaxis and invasion, while STK39/SPAK regulates endothelial cell proliferation (PubMed:25362046). Also acts independently of the WNK1-SPAK/OSR1 kinase cascade by catalyzing phosphorylation of other substrates, such as SYT2, PCF11 and NEDD4L (PubMed:29196535). Mediates phosphorylation of SYT2, regulating SYT2 association with phospholipids and membrane-binding (By similarity). Regulates mRNA export in the nucleus by mediating phosphorylation of PCF11, thereby decreasing the association between PCF11 and POLR2A/RNA polymerase II and promoting mRNA export to the cytoplasm (PubMed:29196535). Acts as a negative regulator of autophagy (PubMed:27911840). Required for the abscission step during mitosis, independently of the WNK1-SPAK/OSR1 kinase cascade (PubMed:21220314). May also play a role in actin cytoskeletal reorganization (PubMed:10660600). Also acts as a scaffold protein independently of its protein kinase activity: negatively regulates cell membrane localization of various transporters and channels, such as SLC4A4, SLC26A6, SLC26A9, TRPV4 and CFTR (By similarity). Involved in the regulation of epithelial Na(+) channel (ENaC) by promoting activation of SGK1 in a kinase-independent manner: probably acts as a scaffold protein that promotes the recruitment of SGK1 to the mTORC2 complex in response to chloride, leading to mTORC2-dependent phosphorylation and activation of SGK1 (PubMed:36373794). Acts as an assembly factor for the ER membrane protein complex independently of its protein kinase activity: associates with EMC2 in the cytoplasm via its amphipathic alpha-helix, and prevents EMC2 ubiquitination and subsequent degradation, thereby promoting EMC2 stabilization (PubMed:33964204)\nKinase-defective isoform specifically expressed in kidney, which acts as a dominant-negative regulator of the longer isoform 1 (PubMed:14645531). Does not directly inhibit WNK4 and has no direct effect on sodium and chloride ion transport (By similarity). Down-regulates sodium-chloride cotransporter activity indirectly by inhibiting isoform 1, it associates with isoform 1 and attenuates its kinase activity (By similarity). In kidney, may play an important role regulating sodium and potassium balance (By similarity)","subunit":"Interacts with WNK3 (By similarity). Interacts with WNK4; inhibiting the activity of WNK4 (By similarity). Interacts with SGK1; promoting its activation (PubMed:36373794). Associates with the mTORC2 complex (PubMed:36373794). Interacts with UVRAG (PubMed:27911840). Interacts (via amphipathic alpha-helix region) with EMC2; promoting the ER membrane protein complex assembly (PubMed:33964204)\nInteracts with isoform 1; inhibiting isoform 1 activity","family":"Belongs to the protein kinase superfamily. Ser/Thr protein kinase family. WNK subfamily","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["10660600","14645531","15883153","16263722","17190791","19665974","19739668","21220314","21321328","22989884","25362046","25477473","27911840","29196535","31656913","33964204","34289367","36318922","36373794"],"location":"Cytoplasm；Nucleus；Cytoplasm, cytoskeleton, spindle","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"泛素化/蛋白稳态；细胞周期/分裂；激酶/磷酸化信号；细胞骨架/纤毛；线粒体/代谢；注释原文：Serine/threonine-protein kinase component of the WNK1-SPAK/OSR1 kinase cascade, which acts as a key regulator of blood pressure and regulatory volume increase by promoting ion influx (PubMed:15883153, PubMed:17190791, PubMed:31656913, PubMed:34289367, PubMed:36318922).","function_evidence":"含实验支持条目；含同源推断，不能当该成员实测；ECO:0000250,ECO:0000269","categories":"泛素化/蛋白稳态；细胞周期/分裂；激酶/磷酸化信号；细胞骨架/纤毛；线粒体/代谢"},"WNT5A":{"hgnc":"HGNC:12784","symbol":"WNT5A","accessions":["P41221"],"name":"Protein Wnt-5a","length":"380","function":"Ligand for members of the frizzled family of seven transmembrane receptors. Can activate or inhibit canonical Wnt signaling, depending on receptor context. In the presence of FZD4, activates beta-catenin signaling. In the presence of ROR2, inhibits the canonical Wnt pathway by promoting beta-catenin degradation through a GSK3-independent pathway which involves down-regulation of beta-catenin-induced reporter gene expression (By similarity). Suppression of the canonical pathway allows chondrogenesis to occur and inhibits tumor formation. Stimulates cell migration. Decreases proliferation, migration, invasiveness and clonogenicity of carcinoma cells and may act as a tumor suppressor (PubMed:15735754). Mediates motility of melanoma cells (PubMed:17426020). Required during embryogenesis for extension of the primary anterior-posterior axis and for outgrowth of limbs and the genital tubercle. Inhibits type II collagen expression in chondrocytes (By similarity)","subunit":"Forms a soluble 1:1 complex with AFM; this prevents oligomerization and is required for prolonged biological activity (PubMed:26902720). The complex with AFM may represent the physiological form in body fluids (PubMed:26902720). Homooligomer; disulfide-linked, leading to inactivation (in vitro). Interacts with PORCN. Interacts with WLS (By similarity). Interacts with glypican GCP3 (PubMed:14610063). Interacts with PKD1 (via extracellular domain) (PubMed:27214281). Interacts with TMEM67 (PubMed:34731008)","family":"Belongs to the Wnt family","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["15735754","17426020"],"location":"Secreted, extracellular space, extracellular matrix；Secreted","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"黏附/受体/细胞表面；注释原文：Ligand for members of the frizzled family of seven transmembrane receptors.","function_evidence":"含实验支持条目；含同源推断，不能当该成员实测；ECO:0000250,ECO:0000269","categories":"黏附/受体/细胞表面"},"WRAP53":{"hgnc":"HGNC:25522","symbol":"WRAP53","accessions":["Q9BUR4"],"name":"Telomerase Cajal body protein 1","length":"548","function":"RNA chaperone that plays a key role in telomere maintenance and RNA localization to Cajal bodies (PubMed:29695869, PubMed:29804836). Specifically recognizes and binds the Cajal body box (CAB box) present in both small Cajal body RNAs (scaRNAs) and telomerase RNA template component (TERC) (PubMed:19285445, PubMed:20351177, PubMed:29695869, PubMed:29804836). Essential component of the telomerase holoenzyme complex, a ribonucleoprotein complex essential for the replication of chromosome termini that elongates telomeres in most eukaryotes (PubMed:19179534, PubMed:20351177, PubMed:26170453, PubMed:29695869). In the telomerase holoenzyme complex, required to stimulate the catalytic activity of the complex (PubMed:27525486, PubMed:29804836). Acts by specifically binding the CAB box of the TERC RNA and controlling the folding of the CR4/CR5 region of the TERC RNA, a critical step for telomerase activity (PubMed:29804836). In addition, also controls telomerase holoenzyme complex localization to Cajal body (PubMed:22547674). During S phase, required for delivery of TERC to telomeres during S phase and for telomerase activity (PubMed:29804836). In addition to its role in telomere maintenance, also required for Cajal body formation, probably by mediating localization of scaRNAs to Cajal bodies (PubMed:19285445, PubMed:21072240). Also plays a role in DNA repair: phosphorylated by ATM in response to DNA damage and relocalizes to sites of DNA double-strand breaks to promote the repair of DNA double-strand breaks (PubMed:25512560, PubMed:27715493). Acts by recruiting the ubiquitin ligase RNF8 to DNA breaks and promote both homologous recombination (HR) and non-homologous end joining (NHEJ) (PubMed:25512560, PubMed:27715493)","subunit":"Component of the telomerase holoenzyme complex composed of one molecule of TERT, one molecule of WRAP53/TCAB1, two molecules of H/ACA ribonucleoprotein complex subunits DKC1, NOP10, NHP2 and GAR1, and a telomerase RNA template component (TERC) (PubMed:19179534, PubMed:20351177, PubMed:26170453, PubMed:29695869). The telomerase holoenzyme complex is associated with TEP1, SMG6/EST1A and POT1 (PubMed:19179534). Interacts with the chaperonin-containing T-complex (TRiC) complex; which mediates the folding of WRAP53/TCAB1 (PubMed:25467444). Interacts with COIL (PubMed:21072240). Interacts with SMN1 (PubMed:21072240). Interacts with RNF8 (PubMed:25512560). Interacts with histone H2AX (PubMed:26734725, PubMed:27715493)","family":"Belongs to the TCAB1 family","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["19179534","19285445","20351177","21072240","22547674","25512560","26170453","27525486","27715493","29695869","29804836"],"location":"Nucleus, Cajal body；Chromosome, telomere；Chromosome","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"泛素化/蛋白稳态；RNA加工/剪接；DNA修复/复制；激酶/磷酸化信号；注释原文：RNA chaperone that plays a key role in telomere maintenance and RNA localization to Cajal bodies (PubMed:29695869, PubMed:29804836).","function_evidence":"含实验支持条目；ECO:0000269","categories":"泛素化/蛋白稳态；RNA加工/剪接；DNA修复/复制；激酶/磷酸化信号"},"WRN":{"hgnc":"HGNC:12791","symbol":"WRN","accessions":["Q14191"],"name":"Bifunctional 3'-5' exonuclease/ATP-dependent helicase WRN","length":"1432","function":"Multifunctional enzyme that has magnesium and ATP-dependent 3'-5' DNA-helicase activity on partially duplex substrates (PubMed:9224595, PubMed:9288107, PubMed:9611231). Also has 3'->5' exonuclease activity towards double-stranded (ds)DNA with a 5'-overhang (PubMed:11863428). Has no nuclease activity towards single-stranded (ss)DNA or blunt-ended dsDNA (PubMed:11863428). Helicase activity is most efficient with (d)ATP, but (d)CTP will substitute with reduced efficiency; strand displacement is enhanced by single-strand binding-protein (heterotrimeric replication protein A complex, RPA1, RPA2, RPA3) (PubMed:9611231). Binds preferentially to DNA substrates containing alternate secondary structures, such as replication forks and Holliday junctions. May play an important role in the dissociation of joint DNA molecules that can arise as products of homologous recombination, at stalled replication forks or during DNA repair. Alleviates stalling of DNA polymerases at the site of DNA lesions. Plays a role in the formation of DNA replication focal centers; stably associates with foci elements generating binding sites for RP-A (By similarity). Plays a role in double-strand break repair after gamma-irradiation (PubMed:9224595, PubMed:9288107, PubMed:9611231). Unwinds some G-quadruplex DNA (d(CGG)n tracts); unwinding seems to occur in both 5'-3' and 3'-5' direction and requires a short single-stranded tail (PubMed:10212265). d(CGG)n tracts have a propensity to assemble into tetraplex structures; other G-rich substrates from a telomeric or IgG switch sequence are not unwound (PubMed:10212265). Depletion leads to chromosomal breaks and genome instability (PubMed:33199508)","subunit":"Monomer, and homooligomer (PubMed:11863428, PubMed:18596042, PubMed:20159463). May exist as homodimer, homotrimer, homotetramer and/or homohexamer (PubMed:11863428, PubMed:18596042, PubMed:20159463). Homotetramer, or homohexamer, when bound to DNA (PubMed:11863428, PubMed:18596042, PubMed:20159463). Interacts via its N-terminal domain with WRNIP1 (By similarity). Interacts with EXO1, PCNA and SUPV3L1 (PubMed:12704184, PubMed:17961633). Interacts with PML (isoform PML-4) (PubMed:21639834). Interacts (via KBM motif) with XRCC5 and XRCC6; promoting recruitment to DNA damage sites (PubMed:27063109). Interacts with RECQL5; this interaction stimulates WRN helicase activity on DNA fork duplexes (PubMed:23180761)","family":"Belongs to the helicase family. RecQ subfamily","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["10212265","11863428","17563354","18596042","19283071","19652551","21639834","27063109","33199508","9224595","9288107","9611231"],"location":"Nucleus, nucleolus；Nucleus；Nucleus, nucleoplasm；Chromosome","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"DNA修复/复制；注释原文：Multifunctional enzyme that has magnesium and ATP-dependent 3'-5' DNA-helicase activity on partially duplex substrates (PubMed:9224595, PubMed:9288107, PubMed:9611231).","function_evidence":"含实验支持条目；含同源推断，不能当该成员实测；ECO:0000250,ECO:0000269","categories":"DNA修复/复制"},"WRNIP1":{"hgnc":"HGNC:20876","symbol":"WRNIP1","accessions":["Q96S55"],"name":"ATPase WRNIP1","length":"665","function":"Functions as a modulator of initiation or reinitiation events during DNA polymerase delta-mediated DNA synthesis. In the presence of ATP, stimulation of DNA polymerase delta-mediated DNA synthesis is decreased. Also plays a role in the innate immune defense against viruses. Stabilizes the RIGI dsRNA interaction and promotes RIGI 'Lys-63'-linked polyubiquitination. In turn, RIGI transmits the signal through mitochondrial MAVS","subunit":"Forms homooligomers (PubMed:18842586), possibly octamers. Directly interacts with POLD1, POLD2 and POLD4 (PubMed:15670210). Interacts with the N-terminal domain of WRN (By similarity). Interacts (via UBZ4-type zinc finger) with monoubiquitin and polyubiquitin (PubMed:17550899, PubMed:18842586). Interacts with TRIM14 and PPP6C; these interactions positively regulate the RIGI signaling pathway (PubMed:29053956)","family":"Belongs to the AAA ATPase family. RarA/MGS1/WRNIP1 subfamily","domains":[],"function_pmids":["15670210","29053956"],"location":"Nucleus; Cytoplasm","shared_sequence_gene_count":"1","source_snapshot":"project UniProt records20261017/18","brief":"Functions as a modulator of initiation or reinitiation events during DNA polymerase delta-mediated DNA synthesis. In the presence of ATP, stimulation of DNA polymerase delta-mediated DNA synthesis is decreased. Also plays a role in the innate immune defense against viruses. Stabilizes the RIGI dsRNA interaction and promotes RIGI 'Lys-63'-linked polyubiquitination. In turn, RIGI transmits the signal through mitochondrial MAVS"},"WTAP":{"hgnc":"HGNC:16846","symbol":"WTAP","accessions":["Q15007"],"name":"Pre-mRNA-splicing regulator WTAP","length":"396","function":"Associated component of the WMM complex, a complex that mediates N6-methyladenosine (m6A) methylation of RNAs, a modification that plays a role in the efficiency of mRNA splicing and RNA processing (PubMed:29507755). Required for accumulation of METTL3 and METTL14 to nuclear speckle (PubMed:24316715, PubMed:24407421, PubMed:24981863). Acts as a mRNA splicing regulator (PubMed:12444081). Regulates G2/M cell-cycle transition by binding to the 3' UTR of CCNA2, which enhances its stability (PubMed:17088532). Impairs WT1 DNA-binding ability and inhibits expression of WT1 target genes (PubMed:17095724)","subunit":"Component of the WMM complex, a N6-methyltransferase complex composed of a catalytic subcomplex, named MAC, and of an associated subcomplex, named MACOM (PubMed:24316715, PubMed:24407421, PubMed:24981863, PubMed:29348140, PubMed:29506078, PubMed:29507755). The MAC subcomplex is composed of METTL3 and METTL14 (PubMed:29507755). The MACOM subcomplex is composed of WTAP, ZC3H13, CBLL1/HAKAI, VIRMA, and, in some cases of RBM15 (RBM15 or RBM15B) (PubMed:29507755). Interacts with WT1 (PubMed:11001926, PubMed:17095724). Also a component of a MACOM-like complex, named WTAP complex, composed of WTAP, ZC3H13, CBLL1, VIRMA, RBM15, BCLAF1 and THRAP3 (PubMed:24100041)","family":"Belongs to the fl(2)d family","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["12444081","17088532","17095724","24316715","24407421","24981863","29507755"],"location":"Nucleus speckle；Nucleus, nucleoplasm；Cytoplasm","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"RNA加工/剪接；注释原文：Associated component of the WMM complex, a complex that mediates N6-methyladenosine (m6A) methylation of RNAs, a modification that plays a role in the efficiency of mRNA splicing and RNA processing (PubMed:29507755).","function_evidence":"含实验支持条目；ECO:0000269","categories":"RNA加工/剪接"},"WWC1":{"hgnc":"HGNC:29435","symbol":"WWC1","accessions":["Q8IX03"],"name":"Protein KIBRA","length":"1113","function":"Regulator of the Hippo signaling pathway, also known as the Salvador-Warts-Hippo (SWH) pathway (PubMed:24682284). Enhances phosphorylation of LATS1 and YAP1 and negatively regulates cell proliferation and organ growth due to a suppression of the transcriptional activity of YAP1, the major effector of the Hippo pathway (PubMed:24682284). Along with NF2 can synergistically induce the phosphorylation of LATS1 and LATS2 and function in the regulation of Hippo signaling pathway (PubMed:20159598). Acts as a transcriptional coactivator of ESR1 which plays an essential role in DYNLL1-mediated ESR1 transactivation (PubMed:16684779). Regulates collagen-stimulated activation of the ERK/MAPK cascade (PubMed:18190796). Modulates directional migration of podocytes (PubMed:18596123). Plays a role in cognition and memory performance (PubMed:18672031). Plays an important role in regulating AMPA-selective glutamate receptors (AMPARs) trafficking underlying synaptic plasticity and learning (By similarity)","subunit":"Homodimer (PubMed:15081397, PubMed:18672031). Forms heterodimers with WWC2 and WWC3 (PubMed:24682284). Interacts with DDN. Interacts with DYNLL1 and histone H3. The interaction with DYNLL1 is mandatory for the recruitment and transactivation functions of ESR1 or DYNLL1 to the target chromatin and the interaction with histone H3 ensures proper regulatory interaction of WWC1-DYNLL1-ESR1 complexes with target chromatin. Interacts (via WW domains) with DDR1 (via PPxY motif) in a collagen-regulated manner. Interacts with PRKCZ (via the protein kinase domain). Forms a tripartite complex with DDR1 and PRKCZ, but predominantly in the absence of collagen. Interacts (via the ADDV motif) with PATJ (via PDZ domain 8). Interacts (via WW domains) with SYNPO (via PPxY motifs). Interacts with NF2 and SNX4. Interacts with DLC1 and PRKCZ (PubMed:24682284). Interacts (via WW domains) with LATS1 and LATS2 (PubMed:24682284)","family":"Belongs to the WWC family. KIBRA subfamily","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["16684779","18190796","18596123","18672031","20159598","24682284"],"location":"Cytoplasm, perinuclear region；Nucleus；Cell projection, ruffle membrane；Cytoplasm, cytosol","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"染色质/转录调控；激酶/磷酸化信号；黏附/受体/细胞表面；注释原文：Regulator of the Hippo signaling pathway, also known as the Salvador-Warts-Hippo (SWH) pathway (PubMed:24682284).","function_evidence":"含实验支持条目；含同源推断，不能当该成员实测；ECO:0000250,ECO:0000269","categories":"染色质/转录调控；激酶/磷酸化信号；黏附/受体/细胞表面"},"WWOX":{"hgnc":"HGNC:12799","symbol":"WWOX","accessions":["Q9NZC7"],"name":"WW domain-containing oxidoreductase","length":"414","function":"Putative oxidoreductase. Acts as a tumor suppressor and plays a role in apoptosis. Required for normal bone development (By similarity). May function synergistically with p53/TP53 to control genotoxic stress-induced cell death. Plays a role in TGFB1 signaling and TGFB1-mediated cell death. May also play a role in tumor necrosis factor (TNF)-mediated cell death. Inhibits Wnt signaling, probably by sequestering DVL2 in the cytoplasm","subunit":"Interacts with TP53, p73/TP73 and MAPK8. Interacts with MAPT/TAU, RUNX2 and HYAL2 (By similarity). Forms a ternary complex with TP53 and MDM2. Interacts with ERBB4, LITAF and WBP1. Interacts with DVL1, DVL2 and DVL3. May interact with FAM189B and SCOTIN. Interacts with TNK2. Interacts with TMEM207. Interacts (via WW domain) with VOPP1 (PubMed:30285739)","family":"Belongs to the short-chain dehydrogenases/reductases (SDR) family","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["11719429","15070730","15548692","16061658","16219768","19366691","19465938"],"location":"Cytoplasm；Nucleus；Mitochondrion；Golgi apparatus；Lysosome","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"免疫/炎症/细胞死亡；线粒体/代谢；发育/分化；注释原文：Putative oxidoreductase.","function_evidence":"含实验支持条目；含同源推断，不能当该成员实测；ECO:0000250,ECO:0000269","categories":"免疫/炎症/细胞死亡；线粒体/代谢；发育/分化"},"WWP1":{"hgnc":"HGNC:17004","symbol":"WWP1","accessions":["Q9H0M0"],"name":"NEDD4-like E3 ubiquitin-protein ligase WWP1","length":"922","function":"E3 ubiquitin-protein ligase which accepts ubiquitin from an E2 ubiquitin-conjugating enzyme in the form of a thioester and then directly transfers the ubiquitin to targeted substrates. Ubiquitinates ERBB4 isoforms JM-A CYT-1 and JM-B CYT-1, KLF2, KLF5 and TP63 and promotes their proteasomal degradation. Ubiquitinates RNF11 without targeting it for degradation. Ubiquitinates and promotes degradation of TGFBR1; the ubiquitination is enhanced by SMAD7. Ubiquitinates SMAD6 and SMAD7. Ubiquitinates and promotes degradation of SMAD2 in response to TGF-beta signaling, which requires interaction with TGIF. Activates the Hippo signaling pathway in response to cell contact inhibition and recruitment to the Crumbs complex at the cell membrane (PubMed:34404733). Monoubiquitinates AMOTL2 which facilitates its interaction with and activation of LATS2 (PubMed:34404733). LATS2 then phosphorylates YAP1, excluding it from the nucleus and therefore ultimately represses YAP1-driven transcription of target genes (PubMed:34404733)","subunit":"Interacts with the Crumbs complex components PALS1 and PATJ; interaction with the Crumbs complex is enhanced by WWP1's interaction with AMOTL2 and facilitates WWP1 localization to the plasma membrane (PubMed:34404733). Interaction with the Crumbs complex promotes WWP1 monoubiquitination of AMOTL2, which activates the Hippo signaling pathway (PubMed:34404733). Binds KLF2 and HIVEP3 (By similarity). Binds SCNN1A, SCNN1B, SCNN1G, WBP1, WBP2, DRPLA and adenovirus type 2 PIII. Interacts with RNF11 (By similarity). Interacts with SPART. Interacts with ERBB4 isoforms JM-B CYT-1 and JM-A CYT-1. Interacts with SMAD1, SMAD2, SMAD3, SMAD5, SMAD6, SMAD7, TGFBR1 and TGFBR2. Associates with the TGFBR1:TGFBR2 receptor complex in presence of SMAD7. Interacts with SKIL isoform 1. Interacts with TP63 isoform 1 and isoform 2. Interacts with STAMBP and RNF11. Interacts with NDFIP1 and NDFIP2 (Probable); this interaction activates the E3 ubiquitin-protein ligase. Interacts with TGIF. Interacts (via WW domains) with ARRDC1, ARRDC2 and ARRDC3 (PubMed:21191027)\n(Microbial infection) Interacts with HTLV-1 protein Gag\n(Microbial infection) Interacts with ebola virus protein VP40","family":"","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["12535537","15221015","15359284","34404733"],"location":"Cytoplasm；Cell membrane；Peripheral membrane protein；Nucleus；Cell junction","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"泛素化/蛋白稳态；染色质/转录调控；激酶/磷酸化信号；注释原文：E3 ubiquitin-protein ligase which accepts ubiquitin from an E2 ubiquitin-conjugating enzyme in the form of a thioester and then directly transfers the ubiquitin to targeted substrates.","function_evidence":"含实验支持条目；ECO:0000269","categories":"泛素化/蛋白稳态；染色质/转录调控；激酶/磷酸化信号"},"WWP2":{"hgnc":"HGNC:16804","symbol":"WWP2","accessions":["O00308"],"name":"NEDD4-like E3 ubiquitin-protein ligase WWP2","length":"870","function":"E3 ubiquitin-protein ligase which accepts ubiquitin from an E2 ubiquitin-conjugating enzyme in the form of a thioester and then directly transfers the ubiquitin to targeted substrates. Polyubiquitinates POU5F1 by 'Lys-63'-linked conjugation and promotes it to proteasomal degradation; in embryonic stem cells (ESCs) the ubiquitination is proposed to regulate POU5F1 protein level. Ubiquitinates EGR2 and promotes it to proteasomal degradation; in T-cells the ubiquitination inhibits activation-induced cell death. Ubiquitinates SLC11A2; the ubiquitination is enhanced by presence of NDFIP1 and NDFIP2. Ubiquitinates RPB1 and promotes it to proteasomal degradation","subunit":"Interacts with POU5F1, RBP1, EGR2 and SLC11A2 (By similarity). Interacts with SCNN1A, SCNN1B, SCNN1G, WBP1, WBP2 and ATN1. Interacts with ERBB4, NDFIP1 and NDFIP2. Interacts with ARRDC4 (PubMed:23236378). Interacts (via WW domains) with ARRDC1 (via PPxY motifs); ubiquitinates ARRDC1 (PubMed:21191027, PubMed:22315426). Interacts (via WW domains) with ARRDC2 and ARRDC3 (PubMed:21191027)\n(Microbial infection) Interacts with adenovirus type 2 PIII","family":"","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["19274063","19651900"],"location":"Nucleus","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"泛素化/蛋白稳态；注释原文：E3 ubiquitin-protein ligase which accepts ubiquitin from an E2 ubiquitin-conjugating enzyme in the form of a thioester and then directly transfers the ubiquitin to targeted substrates.","function_evidence":"含实验支持条目；ECO:0000269","categories":"泛素化/蛋白稳态"},"XAB2":{"hgnc":"HGNC:14089","symbol":"XAB2","accessions":["Q9HCS7"],"name":"Pre-mRNA-splicing factor SYF1","length":"855","function":"Involved in pre-mRNA splicing as component of the spliceosome (PubMed:11991638, PubMed:28076346, PubMed:28502770). Involved in transcription-coupled repair (TCR), transcription and pre-mRNA splicing (PubMed:10944529, PubMed:17981804)","subunit":"Associates with RNA polymerase II, the TCR-specific proteins CKN1/CSA and ERCC6/CSB, and XPA (PubMed:10944529). Identified in the spliceosome C complex (PubMed:11991638, PubMed:28076346, PubMed:28502770). Component of the XAB2 complex, a multimeric protein complex composed of XAB2, PRPF19, AQR, ZNF830, ISY1, and PPIE (PubMed:17981804). Identified in a pentameric intron-binding (IB) complex composed of AQR, XAB2, ISY1, ZNF830 and PPIE that is incorporated into the spliceosome as a preassembled complex (PubMed:25599396). The IB complex does not contain PRPF19 (PubMed:25599396)","family":"Belongs to the crooked-neck family","domains":[],"function_pmids":["10944529","11991638","17981804","28076346","28502770"],"location":"Nucleus","shared_sequence_gene_count":"1","source_snapshot":"project UniProt records20261017/18","brief":"Involved in pre-mRNA splicing as component of the spliceosome (PubMed:11991638, PubMed:28076346, PubMed:28502770). Involved in transcription-coupled repair (TCR), transcription and pre-mRNA splicing (PubMed:10944529, PubMed:17981804)"},"XAGE3":{"symbol":"XAGE3","accessions":["Q8WTP9"],"name":"X antigen family member 3","length":111,"function":"未获得FUNCTION段；不等于没有已发表研究","subunit":"无可用SUBUNIT段","domains":"InterPro: IPR031320 GAGE\nInterPro: IPR008625 GAGE_fam\nPfam: PF05831 GAGE","brief":"本次数据库无可用FUNCTION；只可据蛋白名称/结构域提出方向，不据此称全新功能。","function_evidence":"本次数据库无FUNCTION段；不等于无研究/无功能","categories":"未归类","location":"当前记录无定位注释","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020"},"XAGE5":{"hgnc":"HGNC:30930","symbol":"XAGE5","accessions":["Q8WWM1"],"name":"X antigen family member 5","length":"108","function":"未获得FUNCTION段；不等于没有已发表研究","subunit":"无可用SUBUNIT段","family":"Belongs to the GAGE family","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":[],"location":"当前记录无定位注释","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"本次数据库无可用FUNCTION；只可据蛋白名称/结构域提出方向，不据此称全新功能。","function_evidence":"本次数据库无FUNCTION段；不等于无研究/无功能","categories":"未归类"},"XIAP":{"hgnc":"HGNC:592","symbol":"XIAP","accessions":["P98170"],"name":"E3 ubiquitin-protein ligase XIAP","length":"497","function":"Multi-functional protein which regulates not only caspases and apoptosis, but also modulates inflammatory signaling and immunity, copper homeostasis, mitogenic kinase signaling, cell proliferation, as well as cell invasion and metastasis (PubMed:11257230, PubMed:11257231, PubMed:11447297, PubMed:12121969, PubMed:12620238, PubMed:17560374, PubMed:17967870, PubMed:19473982, PubMed:20154138, PubMed:22103349, PubMed:9230442). Acts as a direct caspase inhibitor (PubMed:11257230, PubMed:11257231, PubMed:12620238). Directly bind to the active site pocket of CASP3 and CASP7 and obstructs substrate entry (PubMed:11257230, PubMed:11257231, PubMed:16352606, PubMed:16916640). Inactivates CASP9 by keeping it in a monomeric, inactive state (PubMed:12620238). Acts as an E3 ubiquitin-protein ligase regulating NF-kappa-B signaling and the target proteins for its E3 ubiquitin-protein ligase activity include: RIPK1, RIPK2, MAP3K2/MEKK2, DIABLO/SMAC, AIFM1, CCS, PTEN and BIRC5/survivin (PubMed:17560374, PubMed:17967870, PubMed:19473982, PubMed:20154138, PubMed:22103349, PubMed:22607974, PubMed:29452636, PubMed:30026309). Acts as an important regulator of innate immunity by mediating 'Lys-63'-linked polyubiquitination of RIPK2 downstream of NOD1 and NOD2, thereby transforming RIPK2 into a scaffolding protein for downstream effectors, ultimately leading to activation of the NF-kappa-B and MAP kinases signaling (PubMed:19667203, PubMed:22607974, PubMed:29452636, PubMed:30026309). 'Lys-63'-linked polyubiquitination of RIPK2 also promotes recruitment of the LUBAC complex to RIPK2 (PubMed:22607974, PubMed:29452636). Regulates the BMP signaling pathway and the SMAD and MAP3K7/TAK1 dependent pathways leading to NF-kappa-B and JNK activation (PubMed:17560374). Ubiquitination of CCS leads to enhancement of its chaperone activity toward its physiologic target, SOD1, rather than proteasomal degradation (PubMed:20154138). Ubiquitination of MAP3K2/MEKK2 and AIFM1 does not lead to proteasomal degradation (PubMed:17967870, PubMed:22103349). Plays a role in copper homeostasis by ubiquitinating COMMD1 and promoting its proteasomal degradation (PubMed:14685266). Can also function as E3 ubiquitin-protein ligase of the NEDD8 conjugation pathway, targeting effector caspases for neddylation and inactivation (PubMed:21145488). Ubiquitinates and therefore mediates the proteasomal degradation of BCL2 in response to apoptosis (PubMed:29020630). Protects cells from spontaneous formation of the ripoptosome, a large multi-protein complex that has the capability to kill cancer cells in a caspase-dependent and caspase-independent manner (PubMed:22095281). Suppresses ripoptosome formation by ubiquitinating RIPK1 and CASP8 (PubMed:22095281). Acts as a positive regulator of Wnt signaling and ubiquitinates TLE1, TLE2, TLE3, TLE4 and AES (PubMed:22304967). Ubiquitination of TLE3 results in inhibition of its interaction with TCF7L2/TCF4 thereby allowing efficient recruitment and binding of the transcriptional coactivator beta-catenin to TCF7L2/TCF4 that is required to initiate a Wnt-specific transcriptional program (PubMed:22304967)","subunit":"Monomer, and homodimer. Part of a complex composed of SEPTIN4 isoform ARTS, XIAP and BCL2, within the complex interacts with SEPTIN4 isoform ARTS and BCL2, SEPTIN4 isoform ARTS acts as a scaffold protein and stabilizes the complex (PubMed:29020630). Interacts (via BIR3 domain) with DIABLO/SMAC; the interaction inhibits apoptotic suppressor activity (PubMed:11140637, PubMed:11257230, PubMed:21695558). Interacts with HTRA2/PRSS25; the interaction inhibits apoptotic suppressor activity (PubMed:11604410). Interacts with TAB1/MAP3K7IP1 and AIFM1. Interaction with DIABLO/SMAC hinders binding of TAB1/MAP3K7IP1 and AIFM1. Interacts with TCF25 and COMMD1. Interacts (via BIR3 domain) with SEPTIN4 isoform ARTS (PubMed:15029247, PubMed:21695558). Interacts (via BIR3 domain) with SEPTIN4 (By similarity). Interacts with RIP1, RIP2, RIP3, RIP4, CCS and USP19. Interacts (via BIR 2 domain and BIR 3 domain) with HAX1 (via C-terminus) and this interaction blocks ubiquitination of XIAP/BIRC4. Interacts with the monomeric form of BIRC5/survivin. Interacts with TLE3 and TCF7L2/TCF4. Interacts (via BIR 3 and RING domains) with PDCL3 (PubMed:19012568)","family":"Belongs to the IAP family","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["11257230","11257231","11447297","12121969","12620238","14685266","16352606","16916640","17560374","17967870","19473982","19667203","20154138","21145488","22095281","22103349","22304967","22607974","29020630","29452636","30026309","9230442"],"location":"Cytoplasm；Nucleus","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"泛素化/蛋白稳态；染色质/转录调控；激酶/磷酸化信号；免疫/炎症/细胞死亡；注释原文：Multi-functional protein which regulates not only caspases and apoptosis, but also modulates inflammatory signaling and immunity, copper homeostasis, mitogenic kinase signaling, cell proliferation, as well as cell invasion and metastasis (PubMed:11257230, PubMed:11257231, PubMed:11447297, PubMed:12121969, PubMed:12620238, PubMed:17560374, PubMed:17967870, PubMed:19473982, PubMed:20154138, PubMed:22103349, PubMed:9230442).","function_evidence":"含实验支持条目；ECO:0000269,ECO:0000303","categories":"泛素化/蛋白稳态；染色质/转录调控；激酶/磷酸化信号；免疫/炎症/细胞死亡"},"XNDC1N":{"hgnc":"HGNC:54661","symbol":"XNDC1N","accessions":["Q6ZNB5"],"name":"Protein XNDC1N","length":"234","function":"未获得FUNCTION段；不等于没有已发表研究","subunit":"无可用SUBUNIT段","family":"","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":[],"location":"当前记录无定位注释","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"本次数据库无可用FUNCTION；只可据蛋白名称/结构域提出方向，不据此称全新功能。","function_evidence":"本次数据库无FUNCTION段；不等于无研究/无功能","categories":"未归类"},"XPC":{"hgnc":"HGNC:12816","symbol":"XPC","accessions":["Q01831"],"name":"DNA repair protein complementing XP-C cells","length":"940","function":"Involved in global genome nucleotide excision repair (GG-NER) by acting as damage sensing and DNA-binding factor component of the XPC complex (PubMed:10734143, PubMed:10873465, PubMed:12509299, PubMed:12547395, PubMed:19609301, PubMed:19941824, PubMed:20028083, PubMed:20649465, PubMed:20798892, PubMed:9734359). Has only a low DNA repair activity by itself which is stimulated by RAD23B and RAD23A. Has a preference to bind DNA containing a short single-stranded segment but not to damaged oligonucleotides (PubMed:10734143, PubMed:19609301, PubMed:20649465). This feature is proposed to be related to a dynamic sensor function: XPC can rapidly screen duplex DNA for non-hydrogen-bonded bases by forming a transient nucleoprotein intermediate complex which matures into a stable recognition complex through an intrinsic single-stranded DNA-binding activity (PubMed:10734143, PubMed:19609301, PubMed:20649465). The XPC complex is proposed to represent the first factor bound at the sites of DNA damage and together with other core recognition factors, XPA, RPA and the TFIIH complex, is part of the pre-incision (or initial recognition) complex (PubMed:10873465, PubMed:12509299, PubMed:12547395, PubMed:19941824, PubMed:20028083, PubMed:20798892, PubMed:9734359). The XPC complex recognizes a wide spectrum of damaged DNA characterized by distortions of the DNA helix such as single-stranded loops, mismatched bubbles or single-stranded overhangs (PubMed:10873465, PubMed:12509299, PubMed:12547395, PubMed:19941824, PubMed:20028083, PubMed:20798892, PubMed:9734359). The orientation of XPC complex binding appears to be crucial for inducing a productive NER (PubMed:10873465, PubMed:12509299, PubMed:12547395, PubMed:19941824, PubMed:20028083, PubMed:20798892, PubMed:9734359). XPC complex is proposed to recognize and to interact with unpaired bases on the undamaged DNA strand which is followed by recruitment of the TFIIH complex and subsequent scanning for lesions in the opposite strand in a 5'-to-3' direction by the NER machinery (PubMed:10873465, PubMed:12509299, PubMed:12547395, PubMed:19941824, PubMed:20028083, PubMed:20798892, PubMed:9734359). Cyclobutane pyrimidine dimers (CPDs) which are formed upon UV-induced DNA damage esacpe detection by the XPC complex due to a low degree of structural perurbation. Instead they are detected by the UV-DDB complex which in turn recruits and cooperates with the XPC complex in the respective DNA repair (PubMed:10873465, PubMed:12509299, PubMed:12547395, PubMed:19941824, PubMed:20028083, PubMed:20798892, PubMed:9734359). In vitro, the XPC:RAD23B dimer is sufficient to initiate NER; it preferentially binds to cisplatin and UV-damaged double-stranded DNA and also binds to a variety of chemically and structurally diverse DNA adducts (PubMed:20028083). XPC:RAD23B contacts DNA both 5' and 3' of a cisplatin lesion with a preference for the 5' side. XPC:RAD23B induces a bend in DNA upon binding. XPC:RAD23B stimulates the activity of DNA glycosylases TDG and SMUG1 (PubMed:20028083)\nIn absence of DNA repair, the XPC complex also acts as a transcription coactivator: XPC interacts with the DNA-binding transcription factor E2F1 at a subset of promoters to recruit KAT2A and histone acetyltransferase complexes (HAT) (PubMed:29973595, PubMed:31527837). KAT2A recruitment specifically promotes acetylation of histone variant H2A.Z.1/H2A.Z, but not H2A.Z.2/H2A.V, thereby promoting expression of target genes (PubMed:31527837)","subunit":"Component of the XPC complex composed of XPC, RAD23B and CETN2 (PubMed:11279143, PubMed:12509233, PubMed:15964821, PubMed:16533048, PubMed:16627479, PubMed:17897675). Interacts with RAD23A; the interaction is suggesting the existence of a functional equivalent variant XPC complex (PubMed:9372924). Interacts with TDG; the interaction is demonstrated using the XPC:RAD23B dimer (PubMed:12505994, PubMed:20798892). Interacts with SMUG1; the interaction is demonstrated using the XPC:RAD23B dimer (PubMed:20798892). Interacts with DDB2 (PubMed:15882621). Interacts with CCNH, GTF2H1 and ERCC3 (PubMed:10734143, PubMed:12509233). Interacts with E2F1 and KAT2A; leading to KAT2A recruitment to promoters and subsequent acetylation of histones (PubMed:29973595, PubMed:31527837)","family":"Belongs to the XPC family","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["10734143","10873465","12509299","12547395","19609301","19941824","20028083","20649465","20798892","29973595","31527837","9734359"],"location":"Nucleus；Chromosome；Cytoplasm","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"染色质/转录调控；DNA修复/复制；注释原文：Involved in global genome nucleotide excision repair (GG-NER) by acting as damage sensing and DNA-binding factor component of the XPC complex (PubMed:10734143, PubMed:10873465, PubMed:12509299, PubMed:12547395, PubMed:19609301, PubMed:19941824, PubMed:20028083, PubMed:20649465, PubMed:20798892, PubMed:9734359).","function_evidence":"含实验支持条目；ECO:0000269","categories":"染色质/转录调控；DNA修复/复制"},"XPO1":{"hgnc":"HGNC:12825","symbol":"XPO1","accessions":["O14980"],"name":"Exportin-1","length":"1071","function":"Mediates the nuclear export of cellular proteins (cargos) bearing a leucine-rich nuclear export signal (NES) and of RNAs. In the nucleus, in association with RANBP3, binds cooperatively to the NES on its target protein and to the GTPase RAN in its active GTP-bound form (Ran-GTP). Docking of this complex to the nuclear pore complex (NPC) is mediated through binding to nucleoporins. Upon transit of a nuclear export complex into the cytoplasm, disassembling of the complex and hydrolysis of Ran-GTP to Ran-GDP (induced by RANBP1 and RANGAP1, respectively) cause release of the cargo from the export receptor. The directionality of nuclear export is thought to be conferred by an asymmetric distribution of the GTP- and GDP-bound forms of Ran between the cytoplasm and nucleus. Involved in U3 snoRNA transport from Cajal bodies to nucleoli. Binds to late precursor U3 snoRNA bearing a TMG cap\n(Microbial infection) Mediates the export of unspliced or incompletely spliced RNAs out of the nucleus from different viruses including HIV-1, HTLV-1 and influenza A. Interacts with, and mediates the nuclear export of HIV-1 Rev and HTLV-1 Rex proteins. Involved in HTLV-1 Rex multimerization","subunit":"Found in a U snRNA export complex with PHAX/RNUXA, NCBP1/CBP80, NCBP2/CBP20, RAN, XPO1 and m7G-capped RNA (By similarity). Component of a nuclear export receptor complex composed of KPNB1, RAN, SNUPN and XPO1. Found in a trimeric export complex with SNUPN, RAN and XPO1. Found in a nuclear export complex with RANBP3 and RAN. Found in a 60S ribosomal subunit export complex with NMD3, RAN, XPO1. Interacts with DDX3X, NMD3, NUP42, NUP88, NUP214, RANBP3 and TERT. Interacts with NEMF (via its N-terminus). Interacts with the monomeric form of BIRC5/survivin deacetylated at 'Lys-129'. Interacts with DTNBP1 and SERTAD2; the interactions translocate DTNBP1 and SERTAD2 out of the nucleus. Interacts with ATF2. Interacts with SLC35G1 and STIM1. Interacts with DCAF8. Interacts with CPEB3 (PubMed:22730302). Interacts with HAX1 (PubMed:23164465). Interacts with BOK; translocates to the cytoplasm (PubMed:16302269). Interacts with HSP90AB1 (PubMed:22022502). Interacts with LRPPRC; interacts with LRPPRC alone and also when LRPPRC is in complex with EIF4E and with EIF4E sensitivity element (4ESE)-containing mRNAs to form an EIF4E-dependent mRNA export complex (PubMed:28325843)\n(Microbial infection) Interacts with HIV-1 Rev\n(Microbial infection) Interacts with HTLV-1 Rex\n(Microbial infection) Interacts with influenza A nucleoprotein\n(Microbial infection) Interacts with Epstein-Barr virus protein BMLF1\n(Microbial infection) Part of a tetrameric complex composed of CRM1, importin alpha/beta dimer and the Venezuelan equine encephalitis virus (VEEV) capsid; this complex blocks the receptor-mediated transport through the nuclear pore\n(Microbial infection) Interacts with SARS-CoV virus protein ORF9b; this interaction mediates protein ORF9b export out of the nucleus","family":"Belongs to the exportin family","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["14612415","15574332","20921223","9311922","9323133","9837918"],"location":"Cytoplasm；Nucleus, nucleoplasm；Nucleus, Cajal body；Nucleus, nucleolus","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"CRM1/exportin-1；Ran依赖的核输出受体。","function_evidence":"含实验支持条目；ECO:0000269","categories":"核质运输；黏附/受体/细胞表面"},"XPO4":{"hgnc":"HGNC:17796","symbol":"XPO4","accessions":["Q9C0E2"],"name":"Exportin-4","length":"1151","function":"Mediates the nuclear export of proteins (cargos), such as EIF5A, SMAD3 and isoform M2 of PKM (PKM2) (PubMed:10944119, PubMed:16449645, PubMed:26787900). In the nucleus binds cooperatively to its cargo and to the GTPase Ran in its active GTP-bound form. Docking of this trimeric complex to the nuclear pore complex (NPC) is mediated through binding to nucleoporins (PubMed:10944119, PubMed:16449645). Upon transit of a nuclear export complex into the cytoplasm, disassembling of the complex and hydrolysis of Ran-GTP to Ran-GDP (induced by RANBP1 and RANGAP1, respectively) cause release of the cargo from the export receptor (PubMed:10944119, PubMed:16449645). XPO4 then return to the nuclear compartment and mediate another round of transport (PubMed:10944119, PubMed:16449645). The directionality of nuclear export is thought to be conferred by an asymmetric distribution of the GTP- and GDP-bound forms of Ran between the cytoplasm and nucleus (PubMed:10944119, PubMed:16449645). Catalyzes the nuclear export of hypusinated EIF5A; a small cytoplasmic protein that enters nucleus and accumulates within nucleolus if not exported back by XPO4 (PubMed:10944119). Specifically mediates nuclear export of isoform M2 of PKM (PKM2) following PKM2 deacetylation by SIRT6 (PubMed:26787900). Also mediates the nuclear import of SOX transcription factors SRY and SOX2 (By similarity)","subunit":"Interacts with Ran and cargo proteins in a GTP-dependent manner","family":"Belongs to the exportin family","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["10944119","16449645","26787900"],"location":"Cytoplasm；Nucleus","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"核质运输；染色质/转录调控；黏附/受体/细胞表面；注释原文：Mediates the nuclear export of proteins (cargos), such as EIF5A, SMAD3 and isoform M2 of PKM (PKM2) (PubMed:10944119, PubMed:16449645, PubMed:26787900).","function_evidence":"含实验支持条目；含同源推断，不能当该成员实测；ECO:0000250,ECO:0000269","categories":"核质运输；染色质/转录调控；黏附/受体/细胞表面"},"XPO5":{"hgnc":"HGNC:17675","symbol":"XPO5","accessions":["Q9HAV4"],"name":"Exportin-5","length":"1204","function":"Mediates the nuclear export of proteins bearing a double-stranded RNA binding domain (dsRBD) and double-stranded RNAs (cargos). XPO5 in the nucleus binds cooperatively to the RNA and to the GTPase Ran in its active GTP-bound form. Proteins containing dsRBDs can associate with this trimeric complex through the RNA. Docking of this complex to the nuclear pore complex (NPC) is mediated through binding to nucleoporins. Upon transit of a nuclear export complex into the cytoplasm, hydrolysis of Ran-GTP to Ran-GDP (induced by RANBP1 and RANGAP1, respectively) cause disassembly of the complex and release of the cargo from the export receptor. XPO5 then returns to the nuclear compartment by diffusion through the nuclear pore complex, to mediate another round of transport. The directionality of nuclear export is thought to be conferred by an asymmetric distribution of the GTP- and GDP-bound forms of Ran between the cytoplasm and nucleus. Overexpression may in some circumstances enhance RNA-mediated gene silencing (RNAi). Mediates nuclear export of isoform 5 of ADAR/ADAR1 in a RanGTP-dependent manner\nMediates the nuclear export of micro-RNA precursors, which form short hairpins (PubMed:14631048, PubMed:14681208, PubMed:15613540). Also mediates the nuclear export of synthetic short hairpin RNAs used for RNA interference. In some circumstances can also mediate the nuclear export of deacylated and aminoacylated tRNAs. Specifically recognizes dsRNAs that lack a 5'-overhang in a sequence-independent manner, have only a short 3'-overhang, and that have a double-stranded length of at least 15 base-pairs (PubMed:19965479). Binding is dependent on Ran-GTP (PubMed:19965479)\n(Microbial infection) Mediates the nuclear export of adenovirus VA1 dsRNA","subunit":"Component of a nuclear export receptor complex composed of XPO5, RAN, dsRNA-binding proteins and dsRNA. Found in a nuclear export complex with XPO5, RAN, EEF1A1, and aminoacylated tRNA. Found in a nuclear export complex with XPO5, RAN, ILF3 and dsRNA. Found in a nuclear export complex with XPO5, RAN and pre-miRNA (PubMed:19965479). Found in a nuclear export complex with XPO5, RAN, ILF3 and minihelix VA1 dsRNA. Found in a nuclear export complex with XPO5, RAN, ILF3, ZNF346 and dsRNA. Interacts with EEF1A1, ILF3, NUP153, NUP214 and ZNF346. Interacts with RAN and cargo proteins in a GTP-dependent manner. Interacts with isoform 5 of ADAR/ADAR1 (via DRBM domains). Interacts with SMAD4; mediates nuclear export of SMAD4 (PubMed:26878725). Interacts with RAN (GTP-bound form) (PubMed:19965479)","family":"Belongs to the exportin family","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["12509441","14631048","14681208","15613540","19965479"],"location":"Nucleus；Cytoplasm","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"核质运输；翻译/核糖体；黏附/受体/细胞表面；注释原文：Mediates the nuclear export of proteins bearing a double-stranded RNA binding domain (dsRBD) and double-stranded RNAs (cargos).","function_evidence":"含实验支持条目；ECO:0000269","categories":"核质运输；翻译/核糖体；黏附/受体/细胞表面"},"XPO6":{"hgnc":"HGNC:19733","symbol":"XPO6","accessions":["Q96QU8"],"name":"Exportin-6","length":"1125","function":"Mediates the nuclear export of actin and profilin-actin complexes in somatic cells","subunit":"Found in a complex with XPO6, Ran, ACTB and PFN1. Interacts with ACTB (PubMed:14592989). Interacts with ACTB in a RanGTP-dependent manner (PubMed:14592989)","family":"Belongs to the exportin family","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["14592989"],"location":"Nucleus；Cytoplasm","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"核质运输；细胞骨架/纤毛；注释原文：Mediates the nuclear export of actin and profilin-actin complexes in somatic cells","function_evidence":"含实验支持条目；ECO:0000269","categories":"核质运输；细胞骨架/纤毛"},"XPO7":{"hgnc":"HGNC:14108","symbol":"XPO7","accessions":["Q9UIA9"],"name":"Exportin-7","length":"1087","function":"Mediates the nuclear export of proteins (cargos) with broad substrate specificity. In the nucleus binds cooperatively to its cargo and to the GTPase Ran in its active GTP-bound form. Docking of this trimeric complex to the nuclear pore complex (NPC) is mediated through binding to nucleoporins. Upon transit of a nuclear export complex into the cytoplasm, disassembling of the complex and hydrolysis of Ran-GTP to Ran-GDP (induced by RANBP1 and RANGAP1, respectively) cause release of the cargo from the export receptor. XPO7 then return to the nuclear compartment and mediate another round of transport. The directionality of nuclear export is thought to be conferred by an asymmetric distribution of the GTP- and GDP-bound forms of Ran between the cytoplasm and nucleus","subunit":"Binds to nucleoporins. Found in a complex with XPO7, EIF4A1, ARHGAP1, VPS26A, VPS29, VPS35 and SFN. Interacts with ARHGAP1 and SFN. Interacts with Ran and cargo proteins in a GTP-dependent manner","family":"Belongs to the exportin family","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["11024021","15282546"],"location":"Cytoplasm；Nucleus","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"核质运输受体，参与蛋白进/出核；不是特定功能团队本身。","function_evidence":"含实验支持条目；ECO:0000269","categories":"核质运输；黏附/受体/细胞表面"},"XPOT":{"hgnc":"HGNC:12826","symbol":"XPOT","accessions":["O43592"],"name":"Exportin-T","length":"962","function":"Mediates the nuclear export of aminoacylated tRNAs. In the nucleus binds to tRNA and to the GTPase Ran in its active GTP-bound form. Docking of this trimeric complex to the nuclear pore complex (NPC) is mediated through binding to nucleoporins. Upon transit of a nuclear export complex into the cytoplasm, disassembling of the complex and hydrolysis of Ran-GTP to Ran-GDP (induced by RANBP1 and RANGAP1, respectively) cause release of the tRNA from the export receptor. XPOT then return to the nuclear compartment and mediate another round of transport. The directionality of nuclear export is thought to be conferred by an asymmetric distribution of the GTP- and GDP-bound forms of Ran between the cytoplasm and nucleus","subunit":"Found in a complex with XPOT, Ran and tRNA. Probably found in a complex with nucleoporins. Interacts with Ran and tRNA in a GTP-dependent manner","family":"Belongs to the exportin family","domains":[],"function_pmids":["12138183","9512417","9660920"],"location":"Nucleus; Cytoplasm","shared_sequence_gene_count":"1","source_snapshot":"project UniProt records20261017/18","brief":"Mediates the nuclear export of aminoacylated tRNAs. In the nucleus binds to tRNA and to the GTPase Ran in its active GTP-bound form. Docking of this trimeric complex to the nuclear pore complex (NPC) is mediated through binding to nucleoporins. Upon transit of a nuclear export complex into the cytoplasm, disassembling of the complex and hydrolysis of Ran-GTP to Ran-GDP (induced by RANBP1 and RANGAP1, respectively) cause release of the tRNA from the export receptor. XPOT then return to the nuclear compartment and mediate another round of transport. The directionality of nuclear export is thought to be conferred by an asymmetric distribution of the GTP- and GDP-bound forms of Ran between the cytoplasm and nucleus"},"XRCC1":{"hgnc":"HGNC:12828","symbol":"XRCC1","accessions":["P18887"],"name":"DNA repair protein XRCC1","length":"633","function":"Scaffold protein involved in DNA single-strand break repair by mediating the assembly of DNA break repair protein complexes (PubMed:11163244, PubMed:28002403). Negatively regulates ADP-ribosyltransferase activity of PARP1 during base-excision repair in order to prevent excessive PARP1 activity (PubMed:28002403, PubMed:34102106, PubMed:34811483). Recognizes and binds poly-ADP-ribose chains: specifically binds auto-poly-ADP-ribosylated PARP1, limiting its activity (PubMed:14500814, PubMed:34102106, PubMed:34811483)","subunit":"Homodimer (PubMed:16397295). Interacts with polynucleotide kinase (PNK), DNA polymerase-beta (POLB) and DNA ligase III (LIG3) (PubMed:19155274, PubMed:19336415). Interacts with APTX and APLF (PubMed:14755728, PubMed:15044383, PubMed:15380105, PubMed:17353262, PubMed:17507382). Interacts with APEX1; the interaction is induced by SIRT1 and increases with the acetylated form of APEX1 (PubMed:19934257). Interacts with (poly-ADP-ribosylated) PARP1 (PubMed:34811483)","family":"","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["11163244","14500814","28002403","34102106","34811483"],"location":"Nucleus；Chromosome","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"DNA修复/复制；注释原文：Scaffold protein involved in DNA single-strand break repair by mediating the assembly of DNA break repair protein complexes (PubMed:11163244, PubMed:28002403).","function_evidence":"含实验支持条目；ECO:0000269","categories":"DNA修复/复制"},"XRCC4":{"hgnc":"HGNC:12831","symbol":"XRCC4","accessions":["Q13426"],"name":"DNA repair protein XRCC4","length":"336","function":"DNA non-homologous end joining (NHEJ) core factor, required for double-strand break repair and V(D)J recombination (PubMed:10757784, PubMed:10854421, PubMed:12517771, PubMed:16412978, PubMed:17124166, PubMed:17290226, PubMed:22228831, PubMed:25597996, PubMed:25742519, PubMed:25934149, PubMed:26100018, PubMed:26774286, PubMed:8548796). Acts as a scaffold protein that regulates recruitment of other proteins to DNA double-strand breaks (DSBs) (PubMed:15385968, PubMed:20852255, PubMed:26774286, PubMed:27437582). Associates with NHEJ1/XLF to form alternating helical filaments that bridge DNA and act like a bandage, holding together the broken DNA until it is repaired (PubMed:21768349, PubMed:21775435, PubMed:22287571, PubMed:26100018, PubMed:27437582, PubMed:28500754). The XRCC4-NHEJ1/XLF subcomplex binds to the DNA fragments of a DSB in a highly diffusive manner and robustly bridges two independent DNA molecules, holding the broken DNA fragments in close proximity to one other (PubMed:27437582). The mobility of the bridges ensures that the ends remain accessible for further processing by other repair factors (PubMed:27437582). Plays a key role in the NHEJ ligation step of the broken DNA during DSB repair via direct interaction with DNA ligase IV (LIG4): the LIG4-XRCC4 subcomplex reseals the DNA breaks after the gap filling is completed (PubMed:10757784, PubMed:10854421, PubMed:12517771, PubMed:17290226, PubMed:19837014, PubMed:9242410). XRCC4 stabilizes LIG4, regulates its subcellular localization and enhances LIG4's joining activity (PubMed:10757784, PubMed:10854421, PubMed:12517771, PubMed:17290226, PubMed:21982441, PubMed:22228831, PubMed:9242410). Binding of the LIG4-XRCC4 subcomplex to DNA ends is dependent on the assembly of the DNA-dependent protein kinase complex DNA-PK to these DNA ends (PubMed:10757784, PubMed:10854421). Promotes displacement of PNKP from processed strand break termini (PubMed:20852255, PubMed:28453785)\nActs as an activator of the phospholipid scramblase activity of XKR4 (PubMed:33725486). This form, which is generated upon caspase-3 (CASP3) cleavage, translocates into the cytoplasm and interacts with XKR4, thereby promoting phosphatidylserine scramblase activity of XKR4 and leading to phosphatidylserine exposure on apoptotic cell surface (PubMed:33725486)","subunit":"Homodimer and homotetramer in solution (PubMed:11080143, PubMed:25574025, PubMed:25670504, PubMed:25941166, PubMed:31548606, PubMed:17567543). Interacts with NHEJ1/XLF; the interaction is direct and is mediated via a head-to-head interaction between N-terminal head regions (PubMed:16439205, PubMed:17567543, PubMed:18158905, PubMed:20558749, PubMed:21768349, PubMed:21775435, PubMed:21936820, PubMed:22228831, PubMed:22287571, PubMed:22658747, PubMed:26100018, PubMed:27437582). Interacts with LIG4; the LIG4-XRCC4 subcomplex has a 1:2 stoichiometry and XRCC4 is required for LIG4 stability (PubMed:11702069, PubMed:12517771, PubMed:17290226, PubMed:19332554, PubMed:21982441, PubMed:22658747, PubMed:24984242, PubMed:25934149, PubMed:9242410, PubMed:9259561, PubMed:17567543). Component of the core long-range non-homologous end joining (NHEJ) complex (also named DNA-PK complex) composed of PRKDC, LIG4, XRCC4, XRCC6/Ku70, XRCC5/Ku86 and NHEJ1/XLF (PubMed:10757784, PubMed:10854421, PubMed:12547193, PubMed:17124166, PubMed:22658747, PubMed:26774286, PubMed:33854234, PubMed:34352203). Additional component of the NHEJ complex includes PAXX (PubMed:16439205). Following autophosphorylation, PRKDC dissociates from DNA, leading to formation of the short-range NHEJ complex, composed of LIG4, XRCC4, XRCC6/Ku70, XRCC5/Ku86 and NHEJ1/XLF (PubMed:33854234). Interacts with PRKDC; the interaction is direct (PubMed:12509254). Interacts with XRCC6/Ku70; the interaction is direct (PubMed:17124166). Interacts with APTX and APLF (PubMed:15380105, PubMed:17353262, PubMed:17396150, PubMed:18077224). Forms a heterotetramer with IFFO1; the interaction involves LIG4-free XRCC4 and leads to the relocalization of IFFO1 to the sites of DNA damage (PubMed:31548606). Interacts with PNKP; mainly interacts with PNKP when phosphorylated at Thr-233, but is also able to interact at much lower level with PNKP when not unphosphorylated (PubMed:15385968, PubMed:20852255, PubMed:28453785). Interacts with POLL (DNA polymerase lambda) (PubMed:30250067)\nInteracts with XKR4; interacts with the processed form of XKR4, which is cleaved by caspase","family":"Belongs to the XRCC4-XLF family. XRCC4 subfamily","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["10757784","10854421","12517771","15385968","16412978","17124166","17290226","19837014","20852255","21768349","21775435","21982441","22228831","22287571","25597996","25742519","25934149","26100018","26774286","27437582","28453785","28500754","33725486","8548796","9242410"],"location":"Nucleus；Chromosome；Cytoplasm","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"DNA修复/复制；激酶/磷酸化信号；线粒体/代谢；注释原文：DNA non-homologous end joining (NHEJ) core factor, required for double-strand break repair and V(D)J recombination (PubMed:10757784, PubMed:10854421, PubMed:12517771, PubMed:16412978, PubMed:17124166, PubMed:17290226, PubMed:22228831, PubMed:25597996, PubMed:25742519, PubMed:25934149, PubMed:26100018, PubMed:26774286, PubMed:8548796).","function_evidence":"含实验支持条目；ECO:0000269","categories":"DNA修复/复制；激酶/磷酸化信号；线粒体/代谢"},"XRCC5":{"hgnc":"HGNC:12833","symbol":"XRCC5","accessions":["P13010"],"name":"DNA repair protein Ku80","length":"732","function":"DNA-binding protein critical for the DNA damage response, specifically in repairing double-strand breaks (DSBs) via the classical non-homologous end joining (NHEJ) pathway. It forms a heterodimer with XRCC6 (Ku70), creating the Ku70:Ku80 heterodimer (Ku complex), which serves as a DNA end-binding complex. It primarily binds DSBs and recruits essential repair factors, assembling the core long-range NHEJ complex to facilitate the alignment and ligation of broken DNA ends (PubMed:11493912, PubMed:33854234, PubMed:34352203). This pathway ensures the rapid repair of cytotoxic and mutagenic DSBs and contributes to the generation of diversity in T-cell receptors and antibodies through mechanisms such as V(D)J recombination (PubMed:9742108). Likely acts as a 5'-deoxyribose-5-phosphate lyase (5'-dRP lyase), catalyzing the beta-elimination of the 5'-deoxyribose-5-phosphate at abasic sites near DSBs. This activity cleans the termini of abasic sites, a common form of nucleotide damage, preparing broken ends for ligation (PubMed:20383123). It may also possess 3'-5' DNA helicase activity, although this has not been confirmed in vivo, and its physiological significance remains unclear (PubMed:7957065). Beyond DNA repair, the protein contributes to telomere maintenance (PubMed:29490055). It is also implicated in transcriptional regulation, acting as a cofactor for various transcription factors (PubMed:12145306, PubMed:8621488). It plays a role in the regulation of DNA virus-mediated innate immune response by assembling into the HDP-RNP complex, a complex that serves as a platform for IRF3 phosphorylation and subsequent innate immune response activation through the cGAS-STING pathway (PubMed:28712728). Can also bind RNAs and recruits PRKDC to a wide range of cellular RNAs, including the U3 small nucleolar RNA, playing a role in the biogenesis of ribosomal RNAs (PubMed:32103174)","subunit":"Heterodimer composed of XRCC5/Ku80 and XRCC6/Ku70; heterodimerization stabilizes XRCC5 protein (PubMed:11493912, PubMed:22442688, PubMed:25670504, PubMed:25941166, PubMed:35545041). Component of the core long-range non-homologous end joining (NHEJ) complex (also named DNA-PK complex) composed of PRKDC, LIG4, XRCC4, XRCC6/Ku70, XRCC5/Ku86 and NHEJ1/XLF (PubMed:11493912, PubMed:22442688, PubMed:25670504, PubMed:25941166, PubMed:33854234, PubMed:34352203). Additional component of the NHEJ complex includes PAXX (PubMed:25574025, PubMed:25670504, PubMed:25941166, PubMed:27601299). Following autophosphorylation, PRKDC dissociates from DNA, leading to formation of the short-range NHEJ complex, composed of LIG4, XRCC4, XRCC6/Ku70, XRCC5/Ku86 and NHEJ1/XLF (PubMed:33854234). The XRCC5-XRCC6 dimer also associates with NAA15, and this complex displays DNA binding activity towards the osteocalcin FGF response element (OCFRE) (PubMed:12145306). In addition, XRCC5 binds to the osteoblast-specific transcription factors MSX2 and RUNX2 (PubMed:12145306). Interacts with ELF3 (PubMed:15075319). Interacts with APLF (via KBM motif) (PubMed:17353262, PubMed:17396150, PubMed:23689425, PubMed:27063109, PubMed:31733588). The XRCC5/XRCC6 dimer associates in a DNA-dependent manner with APEX1 (PubMed:8621488). Identified in a complex with DEAF1 and XRCC6. Interacts with NR4A3; the DNA-dependent protein kinase complex DNA-PK phosphorylates and activates NR4A3 and prevents NR4A3 ubiquitinylation and degradation (PubMed:25852083). Interacts with RNF138 (PubMed:26502055). Interacts with CYREN isoform 1 (CYREN-1) and isoform 4 (CYREN-2) (via KBM motif) (PubMed:24610814, PubMed:27063109, PubMed:28959974). Interacts with WRN (via KBM motif) (PubMed:27063109). Interacts (via N-terminus) with HSF1 (via N-terminus); this interaction is direct and prevents XRCC5/XRCC6 heterodimeric binding and non-homologous end joining (NHEJ) repair activities induced by ionizing radiation (IR) (PubMed:26359349). Interacts with DHX9; this interaction occurs in a RNA-dependent manner (PubMed:14704337). Part of the HDP-RNP complex composed of at least HEXIM1, PRKDC, XRCC5, XRCC6, paraspeckle proteins (SFPQ, NONO, PSPC1, RBM14, and MATR3) and NEAT1 RNA (PubMed:28712728). Interacts with ERCC6 (PubMed:26030138). The XRCC5-XRCC6 dimer associates with ALKBH2. Interacts with TPRN; TPRN interacts with a number of DNA damage response proteins, is recruited to sites of DNA damage and may play a role in DNA damage repair (PubMed:23213405). Interacts with ERCC6L2 (By similarity)\n(Microbial infection) Interacts with human T-cell leukemia virus 1/HTLV-1 protein HBZ\n(Microbial infection) Interacts with vaccinia virus protein C16; this interaction disrupts the binding of XRCC5/KU80 and XRCC6/KU70 heterodimer to DNA","family":"Belongs to the ku80 family","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["11493912","12145306","20383123","24098118","28712728","29490055","32103174","33854234","34352203","7957065","8621488","9742108"],"location":"Nucleus；Nucleus, nucleolus；Chromosome","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"Ku80，与Ku70形成DNA末端识别复合物，参与NHEJ。","function_evidence":"含实验支持条目；ECO:0000269","categories":"染色质/转录调控；DNA修复/复制；激酶/磷酸化信号；翻译/核糖体；免疫/炎症/细胞死亡；黏附/受体/细胞表面"},"XRCC6":{"hgnc":"HGNC:4055","symbol":"XRCC6","accessions":["P12956"],"name":"DNA repair protein Ku70","length":"609","function":"DNA-binding protein critical for the DNA damage response, specifically in repairing double-strand breaks (DSBs) via the classical non-homologous end joining (NHEJ) pathway. It forms a heterodimer with XRCC5 (Ku80), creating the Ku70:Ku80 heterodimer (Ku complex), which serves as a DNA end-binding complex. It primarily binds DSBs and recruits essential repair factors, assembling the core long-range NHEJ complex to facilitate the alignment and ligation of broken DNA ends (PubMed:11493912, PubMed:20493174, PubMed:33854234, PubMed:34352203, PubMed:9742108). This pathway ensures the rapid repair of cytotoxic and mutagenic DSBs and contributes to the generation of diversity in T-cell receptors and antibodies through mechanisms such as V(D)J recombination (PubMed:9742108). Likely acts as a 5'-deoxyribose-5-phosphate lyase (5'-dRP lyase), catalyzing the beta-elimination of the 5'-deoxyribose-5-phosphate at abasic sites near DSBs. This activity cleans the termini of abasic sites, a common form of nucleotide damage, preparing broken ends for ligation (PubMed:20383123). It may also possess 3'-5' DNA helicase activity, although this has not been confirmed in vivo, and its physiological significance remains unclear (PubMed:7957065). Beyond DNA repair, the protein contributes to telomere maintenance (PubMed:29490055). It is also implicated in transcriptional regulation, acting as a cofactor for various transcription factors (PubMed:12145306, PubMed:8621488). It plays a role in the regulation of DNA virus-mediated innate immune response by assembling into the HDP-RNP complex, a complex that serves as a platform for IRF3 phosphorylation and subsequent innate immune response activation through the cGAS-STING pathway (PubMed:28712728). Can also bind RNAs and recruits PRKDC to a wide range of cellular RNAs, including the U3 small nucleolar RNA, playing a role in the biogenesis of ribosomal RNAs (PubMed:32103174). Additionally, it negatively regulates apoptosis by interacting with BAX, sequestering it from the mitochondria, and may possess deubiquitination activity targeting BAX (PubMed:15023334, PubMed:18362350, PubMed:35545041)","subunit":"Forms a heterodimer with XRCC5/Ku80 to form the Ku70:Ku80 complex (Ku); heterodimerization stabilizes XRCC5 protein (PubMed:11493912, PubMed:35545041). Component of the core long-range non-homologous end joining (NHEJ) complex (also named DNA-PK complex) composed of PRKDC, LIG4, XRCC4, XRCC6/Ku70, XRCC5/Ku86 and NHEJ1/XLF (PubMed:12509254, PubMed:12547193, PubMed:25670504, PubMed:25941166, PubMed:33854234, PubMed:34352203, PubMed:9742108). Additional component of the NHEJ complex includes PAXX (PubMed:25574025, PubMed:27601299, PubMed:27705800). Following autophosphorylation, PRKDC dissociates from DNA, leading to formation of the short-range NHEJ complex, composed of LIG4, XRCC4, XRCC6/Ku70, XRCC5/Ku86 and NHEJ1/XLF (PubMed:33854234). The XRCC5-XRCC6 dimer also associates with NAA15, and this complex binds to the osteocalcin promoter and activates osteocalcin expression (PubMed:12145306). In addition, XRCC6 interacts with the osteoblast-specific transcription factors MSX2, RUNX2 and DLX5 (PubMed:12145306). Interacts with ELF3 (PubMed:15075319). Interacts with ATP23 (PubMed:10219089). The XRCC5-XRRC6 dimer associates in a DNA-dependent manner with APEX1 (PubMed:8621488). Binds to CDK9 isoform 2 (PubMed:20493174). Identified in a complex with DEAF1 and XRCC5 (PubMed:22442688). Interacts with DEAF1 (via the SAND domain); the interaction is direct and may be inhibited by DNA-binding (PubMed:22442688). Interacts with CLU (By similarity). Interacts with NR4A3; the DNA-dependent protein kinase complex DNA-PK phosphorylates and activates NR4A3 and prevents NR4A3 ubiquitinylation and degradation (PubMed:25852083). Interacts with CYREN isoform 1 (CYREN-1) and isoform 4 (CYREN-2) (via KBM motif) (PubMed:24610814, PubMed:27063109, PubMed:28959974). Interacts (via N-terminus) with HSF1 (via N-terminus); this interaction is direct and prevents XRCC5/XRCC6 heterodimeric binding and non-homologous end joining (NHEJ) repair activities induced by ionizing radiation (IR) (PubMed:26359349). Part of the HDP-RNP complex composed of at least HEXIM1, PRKDC, XRCC5, XRCC6, paraspeckle proteins (SFPQ, NONO, PSPC1, RBM14, and MATR3) and NEAT1 RNA (PubMed:28712728). Interacts with HMBOX1 (PubMed:23685356). Interacts with ATF7; involved in ATF7 lolcaization to telomeres (PubMed:29490055). Interacts with APLF (via KBM motif) (PubMed:23689425, PubMed:27063109). Interacts with WRN (via KBM motif) (PubMed:27063109). The XRCC5-XRCC6 dimer associates with ALKBH2. Interacts with TPRN; TPRN interacts with a number of DNA damage response proteins, is recruited to sites of DNA damage and may play a role in DNA damage repair (PubMed:23213405). When not acetylated, interacts with BAX (PubMed:15023334). Interacts with ERCC6L2 (By similarity)\n(Microbial infection) Interacts with human T-cell leukemia virus 1/HTLV-1 protein HBZ\n(Microbial infection) Interacts with vaccinia virus protein C16; this interaction disrupts the binding of XRCC5/KU80 and XRCC6/KU70 heterodimer to DNA","family":"Belongs to the ku70 family","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["11493912","12145306","15023334","18362350","20383123","20493174","28712728","29490055","32103174","33854234","34352203","35545041","7957065","8621488","9742108"],"location":"Nucleus；Chromosome；Cytoplasm","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"Ku70，与Ku80形成DNA末端识别复合物，参与NHEJ。","function_evidence":"含实验支持条目；ECO:0000269","categories":"泛素化/蛋白稳态；染色质/转录调控；DNA修复/复制；激酶/磷酸化信号；翻译/核糖体；免疫/炎症/细胞死亡；线粒体/代谢；黏附/受体/细胞表面"},"XRN2":{"hgnc":"HGNC:12836","symbol":"XRN2","accessions":["Q9H0D6"],"name":"5'-3' exoribonuclease 2","length":"950","function":"Possesses 5'->3' exoribonuclease activity (By similarity). May promote the termination of transcription by RNA polymerase II. During transcription termination, cleavage at the polyadenylation site liberates a 5' fragment which is subsequently processed to form the mature mRNA and a 3' fragment which remains attached to the elongating polymerase. The processive degradation of this 3' fragment by this protein may promote termination of transcription. Binds to RNA polymerase II (RNAp II) transcription termination R-loops formed by G-rich pause sites (PubMed:21700224)","subunit":"Interacts with POLR2A and SMN1/SMN2 (PubMed:26700805). Interacts with CDKN2AIP and NKRF (PubMed:24462208). Interacts with XTBD1; the interaction is direct (PubMed:26779609). Interacts with TRIM71 (via NHL repeats) in an RNA-dependent manner (PubMed:23125361). Interacts with DHX34; the interaction is RNA-independent (PubMed:25220460)","family":"Belongs to the 5'-3' exonuclease family. XRN2/RAT1 subfamily","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["15565158","16648491","21700224"],"location":"Nucleus, nucleolus","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"染色质/转录调控；注释原文：Possesses 5'->3' exoribonuclease activity (By similarity).","function_evidence":"含实验支持条目；含同源推断，不能当该成员实测；ECO:0000250,ECO:0000269","categories":"染色质/转录调控"},"XYLB":{"hgnc":"HGNC:12839","symbol":"XYLB","accessions":["O75191"],"name":"Xylulose kinase","length":"536","function":"Phosphorylates D-xylulose to produce D-xylulose 5-phosphate, a molecule that may play an important role in the regulation of glucose metabolism and lipogenesis","subunit":"Monomer","family":"Belongs to the FGGY kinase family","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["23179721"],"location":"当前记录无定位注释","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"激酶/磷酸化信号；线粒体/代谢；注释原文：Phosphorylates D-xylulose to produce D-xylulose 5-phosphate, a molecule that may play an important role in the regulation of glucose metabolism and lipogenesis","function_evidence":"含实验支持条目；ECO:0000269","categories":"激酶/磷酸化信号；线粒体/代谢"},"YAF2":{"hgnc":"HGNC:17363","symbol":"YAF2","accessions":["Q8IY57"],"name":"YY1-associated factor 2","length":"180","function":"Binds to MYC and inhibits MYC-mediated transactivation. Also binds to MYCN and enhances MYCN-dependent transcriptional activation. Increases calpain 2-mediated proteolysis of YY1 in vitro. Component of the E2F6.com-1 complex, a repressive complex that methylates 'Lys-9' of histone H3, suggesting that it is involved in chromatin-remodeling","subunit":"Interacts with MYC, MYCN, RNF2/RING1B and YY1. Part of the E2F6.com-1 complex in G0 phase composed of E2F6, MGA, MAX, TFDP1, CBX3, BAT8, EUHMTASE1, RING1, RNF2, MBLR, L3MBTL2 and YAF2","family":"","domains":[],"function_pmids":["11593398","12706874","9016636"],"location":"Nucleus","shared_sequence_gene_count":"1","source_snapshot":"project UniProt records20261017/18","brief":"Binds to MYC and inhibits MYC-mediated transactivation. Also binds to MYCN and enhances MYCN-dependent transcriptional activation. Increases calpain 2-mediated proteolysis of YY1 in vitro. Component of the E2F6.com-1 complex, a repressive complex that methylates 'Lys-9' of histone H3, suggesting that it is involved in chromatin-remodeling"},"YAP1":{"hgnc":"HGNC:16262","symbol":"YAP1","accessions":["P46937"],"name":"Transcriptional coactivator YAP1","length":"504","function":"Transcriptional regulator with dual roles as a coactivator and corepressor. Critical downstream regulatory target in the Hippo signaling pathway, crucial for organ size control and tumor suppression by restricting proliferation and promoting apoptosis (PubMed:17974916, PubMed:18280240, PubMed:18579750, PubMed:21364637, PubMed:30447097). The Hippo signaling pathway core involves a kinase cascade featuring STK3/MST2 and STK4/MST1, along with its regulatory partner SAV1, which phosphorylates and activates LATS1/2 in complex with their regulatory protein, MOB1. This activation leads to the phosphorylation and inactivation of the YAP1 oncoprotein and WWTR1/TAZ (PubMed:18158288). Phosphorylation of YAP1 by LATS1/2 prevents its nuclear translocation, thereby regulating the expression of its target genes (PubMed:18158288, PubMed:26598551, PubMed:34404733). The transcriptional regulation of gene expression requires TEAD transcription factors and modulates cell growth, anchorage-independent growth, and induction of epithelial-mesenchymal transition (EMT) (PubMed:18579750). Plays a key role in tissue tension and 3D tissue shape by regulating the cortical actomyosin network, acting via ARHGAP18, a Rho GTPase activating protein that suppresses F-actin polymerization (PubMed:25778702). It also suppresses ciliogenesis by acting as a transcriptional corepressor of TEAD4 target genes AURKA and PLK1 (PubMed:25849865). In conjunction with WWTR1, regulates TGFB1-dependent SMAD2 and SMAD3 nuclear accumulation (By similarity). Synergizes with WBP2 to enhance PGR activity (PubMed:16772533). Promotes keratinocyte proliferation (PubMed:32369015)\nActivates the C-terminal fragment (CTF) of ERBB4 (isoform 3)","subunit":"Part of a complex when phosphorylated that contains DSG3, PKP1, YAP1 and YWHAG; the complex is required for localization of DSG3 and YAP1 to the cell membrane in keratinocytes (PubMed:31835537). Binds to the SH3 domain of the YES kinase. Binds to WBP1 and WBP2 (PubMed:9202023). Binds, in vitro, through the WW1 domain, to neural isoforms of ENAH that contain the PPSY motif (By similarity). The phosphorylated form interacts with YWHAB (PubMed:17974916). Interacts (via WW domains) with LATS1 (via PPxY motif 2) (PubMed:18158288). Interacts with LATS2 (PubMed:18158288). Interacts with TEAD1, TEAD2, TEAD3 and TEAD4 (PubMed:18579750, PubMed:20123905, PubMed:20123908). Interacts with TP73 (PubMed:18280240). Interacts with RUNX1 (PubMed:18280240). Interacts with HCK (PubMed:17535448). Interacts (via WW domains) with PTPN14 (via PPxY motif 2); this interaction leads to the cytoplasmic sequestration of YAP1 and inhibits its transcriptional coactivator activity (PubMed:22525271). Interacts (when phosphorylated at Ser-127) with SMAD2, SMAD3 and WWTR1 (By similarity). Interacts with PRRG2 (via cytoplasmic domain) (PubMed:17502622). Interacts (via WW domains) with PRRG4 (via cytoplasmic domain) (PubMed:23873930). Interacts (phosphorylated) with CLDN18; the interaction sequesters YAP1 away from the nucleus and thereby restricts transcription of YAP1 target genes (By similarity). Interacts with SMAD1 (PubMed:21685363). Interacts with AMOTL2, the interaction is required for ubiquitination of AMOTL2 and localization of YAP1 to tight junctions (PubMed:21205866, PubMed:26598551). Interacts with AMOT isoform 1; the interaction facilitates translocation of YAP1 to the cytoplasm and tight junctions (PubMed:21205866). Interacts with SFN; the interaction promotes sequestration of YAP1 in the cytoplasm (By similarity). Interacts with YWHAG (By similarity)\nInteracts (via WW domain 1) with isoform 3 of ERBB4 (via PPxY motif 2)","family":"Belongs to the YAP1 family","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["12807903","16772533","17974916","18158288","18280240","18579750","21364637","25778702","25849865","26598551","30447097","32369015","34404733"],"location":"Cytoplasm；Nucleus；Cell junction, tight junction；Cell membrane","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"染色质/转录调控；激酶/磷酸化信号；细胞骨架/纤毛；免疫/炎症/细胞死亡；注释原文：Transcriptional regulator with dual roles as a coactivator and corepressor.","function_evidence":"含实验支持条目；含同源推断，不能当该成员实测；ECO:0000250,ECO:0000269","categories":"染色质/转录调控；激酶/磷酸化信号；细胞骨架/纤毛；免疫/炎症/细胞死亡"},"YARS1":{"hgnc":"HGNC:12840","symbol":"YARS1","accessions":["P54577"],"name":"Tyrosine--tRNA ligase, cytoplasmic","length":"528","function":"Tyrosine--tRNA ligase that catalyzes the attachment of tyrosine to tRNA(Tyr) in a two-step reaction: tyrosine is first activated by ATP to form Tyr-AMP and then transferred to the acceptor end of tRNA(Tyr) (Probable) (PubMed:25533949). Also acts as a positive regulator of poly-ADP-ribosylation in the nucleus, independently of its tyrosine--tRNA ligase activity (PubMed:25533949). Activity is switched upon resveratrol-binding: resveratrol strongly inhibits the tyrosine--tRNA ligase activity and promotes relocalization to the nucleus, where YARS1 specifically stimulates the poly-ADP-ribosyltransferase activity of PARP1 (PubMed:25533949)","subunit":"Homodimer (PubMed:12427973, PubMed:14671330, PubMed:30304524). Interacts (when binding to resveratrol) with PARP1; interaction stimulates the poly-ADP-ribosyltransferase activity of PARP1 (PubMed:25533949)","family":"Belongs to the class-I aminoacyl-tRNA synthetase family","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["16429158","25533949","9162081"],"location":"Cytoplasm；Nucleus","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"翻译/核糖体；注释原文：Tyrosine--tRNA ligase that catalyzes the attachment of tyrosine to tRNA(Tyr) in a two-step reaction: tyrosine is first activated by ATP to form Tyr-AMP and then transferred to the acceptor end of tRNA(Tyr) (Probable) (PubMed:25533949).","function_evidence":"含实验支持条目；ECO:0000269,ECO:0000305","categories":"翻译/核糖体"},"YARS2":{"hgnc":"HGNC:24249","symbol":"YARS2","accessions":["Q9Y2Z4"],"name":"Tyrosine--tRNA ligase, mitochondrial","length":"477","function":"Catalyzes the attachment of tyrosine to tRNA(Tyr) in a two-step reaction: tyrosine is first activated by ATP to form Tyr-AMP and then transferred to the acceptor end of tRNA(Tyr)","subunit":"Homodimer","family":"Belongs to the class-I aminoacyl-tRNA synthetase family","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["15779907","17997975"],"location":"Mitochondrion matrix","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"翻译/核糖体；线粒体/代谢；注释原文：Catalyzes the attachment of tyrosine to tRNA(Tyr) in a two-step reaction: tyrosine is first activated by ATP to form Tyr-AMP and then transferred to the acceptor end of tRNA(Tyr)","function_evidence":"含实验支持条目；ECO:0000269","categories":"翻译/核糖体；线粒体/代谢"},"YBEY":{"hgnc":"HGNC:1299","symbol":"YBEY","accessions":["P58557"],"name":"Endoribonuclease YbeY","length":"167","function":"Single strand-specific metallo-endoribonuclease involved in rRNA maturation","subunit":"无可用SUBUNIT段","family":"Belongs to the endoribonuclease YbeY family","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["28153719"],"location":"Nucleus","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"；注释原文：Single strand-specific metallo-endoribonuclease involved in rRNA maturation","function_evidence":"数据库整理/推断；按原文限定；ECO:0000305","categories":"未归类"},"YBX1":{"hgnc":"HGNC:8014","symbol":"YBX1","accessions":["P67809"],"name":"Y-box-binding protein 1","length":"324","function":"DNA- and RNA-binding protein involved in various processes, such as translational repression, RNA stabilization, mRNA splicing, DNA repair and transcription regulation (PubMed:10817758, PubMed:11698476, PubMed:14718551, PubMed:18809583, PubMed:31358969, PubMed:8188694). Predominantly acts as a RNA-binding protein: binds preferentially to the 5'-[CU]CUGCG-3' RNA motif and specifically recognizes mRNA transcripts modified by C5-methylcytosine (m5C) (PubMed:19561594, PubMed:31358969). Promotes mRNA stabilization: acts by binding to m5C-containing mRNAs and recruiting the mRNA stability maintainer ELAVL1, thereby preventing mRNA decay (PubMed:10817758, PubMed:11698476, PubMed:31358969). Component of the CRD-mediated complex that promotes MYC mRNA stability (PubMed:19029303). Contributes to the regulation of translation by modulating the interaction between the mRNA and eukaryotic initiation factors (By similarity). Plays a key role in RNA composition of extracellular exosomes by defining the sorting of small non-coding RNAs, such as tRNAs, Y RNAs, Vault RNAs and miRNAs (PubMed:27559612, PubMed:29073095). Probably sorts RNAs in exosomes by recognizing and binding C5-methylcytosine (m5C)-containing RNAs (PubMed:28341602, PubMed:29073095). Acts as a key effector of epidermal progenitors by preventing epidermal progenitor senescence: acts by regulating the translation of a senescence-associated subset of cytokine mRNAs, possibly by binding to m5C-containing mRNAs (PubMed:29712925). Also involved in pre-mRNA alternative splicing regulation: binds to splice sites in pre-mRNA and regulates splice site selection (PubMed:12604611). Binds to TSC22D1 transcripts, thereby inhibiting their translation and negatively regulating TGF-beta-mediated transcription of COL1A2 (By similarity). Also able to bind DNA: regulates transcription of the multidrug resistance gene MDR1 is enhanced in presence of the APEX1 acetylated form at 'Lys-6' and 'Lys-7' (PubMed:18809583). Binds to promoters that contain a Y-box (5'-CTGATTGGCCAA-3'), such as MDR1 and HLA class II genes (PubMed:18809583, PubMed:8188694). Promotes separation of DNA strands that contain mismatches or are modified by cisplatin (PubMed:14718551). Has endonucleolytic activity and can introduce nicks or breaks into double-stranded DNA, suggesting a role in DNA repair (PubMed:14718551). The secreted form acts as an extracellular mitogen and stimulates cell migration and proliferation (PubMed:19483673)","subunit":"Homodimer in the presence of ATP (PubMed:10817758, PubMed:11851341). Component of the coding region determinant (CRD)-mediated complex, composed of DHX9, HNRNPU, IGF2BP1, SYNCRIP and YBX1 (PubMed:19029303). Identified in a IGF2BP1-dependent mRNP granule complex containing untranslated mRNAs (PubMed:17289661). Component of the U11/U12 snRNPs that are part of the U12-type spliceosome (PubMed:15146077). Identified in a histone pre-mRNA complex, at least composed of ERI1, LSM11, SLBP, SNRPB, SYNCRIP and YBX1 (By similarity). Interacts with IGF2BP1 and RBBP6 (PubMed:17289661, PubMed:18851979). Component of cytoplasmic messenger ribonucleoprotein particles (mRNPs) (PubMed:19029303). Interacts with AKT1, MBNL1, SFRS9, SFRS12, ALYREF/THOC4, MSH2, XRCC5, WRN and NCL (PubMed:12604611, PubMed:14559993, PubMed:14718551, PubMed:15806160, PubMed:18335541). Interacts (via C-terminus) with APEX1 (via N-terminus); the interaction is increased with APEX1 acetylated at 'Lys-6' and 'Lys-7' (PubMed:18809583). Interacts with AGO1 and AGO2 (PubMed:17932509). Interacts with ANKRD2 (PubMed:15136035). Interacts with DERA (PubMed:25229427). Interacts with FMR1; this interaction occurs in association with polyribosome (By similarity). Interacts with ZBTB7B (By similarity). Interacts with HDGF (isoform 1) (PubMed:26845719). Interacts with ELAVL1; leading to ELAVL1 recruitment on C5-methylcytosine (m5C)-containing mRNAs and subsequent mRNA stability (PubMed:31358969). Interacts with PURB (By similarity)","family":"Belongs to the YBX1 family","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["10817758","11698476","12604611","14718551","18809583","19029303","19483673","19561594","27559612","28341602","29073095","29712925","31358969","8188694"],"location":"Cytoplasm；Nucleus；Cytoplasmic granule；Secreted；Secreted, extracellular exosome；Cytoplasm, P-body","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"RNA加工/剪接；染色质/转录调控；DNA修复/复制；翻译/核糖体；黏附/受体/细胞表面；注释原文：DNA- and RNA-binding protein involved in various processes, such as translational repression, RNA stabilization, mRNA splicing, DNA repair and transcription regulation (PubMed:10817758, PubMed:11698476, PubMed:14718551, PubMed:18809583, PubMed:31358969, PubMed:8188694).","function_evidence":"含实验支持条目；含同源推断，不能当该成员实测；ECO:0000250,ECO:0000269","categories":"RNA加工/剪接；染色质/转录调控；DNA修复/复制；翻译/核糖体；黏附/受体/细胞表面"},"YBX2":{"hgnc":"HGNC:17948","symbol":"YBX2","accessions":["Q9Y2T7"],"name":"Y-box-binding protein 2","length":"364","function":"Major constituent of messenger ribonucleoprotein particles (mRNPs). Involved in the regulation of the stability and/or translation of germ cell mRNAs. Binds to Y-box consensus promoter element. Binds to full-length mRNA with high affinity in a sequence-independent manner. Binds to short RNA sequences containing the consensus site 5'-UCCAUCA-3' with low affinity and limited sequence specificity. Its binding with maternal mRNAs is necessary for its cytoplasmic retention. May mark specific mRNAs (those transcribed from Y-box promoters) in the nucleus for cytoplasmic storage, thereby linking transcription and mRNA storage/translational delay (By similarity)","subunit":"Found in a mRNP complex with PABPC1 and YBX3. Found in a mRNP complex with ZAR1 and ZAR1L","family":"","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":[],"location":"Cytoplasm；Nucleus","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"RNA加工/剪接；染色质/转录调控；翻译/核糖体；注释原文：Major constituent of messenger ribonucleoprotein particles (mRNPs).","function_evidence":"含同源推断，不能当该成员实测；ECO:0000250","categories":"RNA加工/剪接；染色质/转录调控；翻译/核糖体"},"YBX3":{"hgnc":"HGNC:2428","symbol":"YBX3","accessions":["P16989"],"name":"Y-box-binding protein 3","length":"372","function":"Binds to the GM-CSF promoter. Seems to act as a repressor. Also binds to full-length mRNA and to short RNA sequences containing the consensus site 5'-UCCAUCA-3'. May have a role in translation repression (By similarity)","subunit":"Found in a mRNP complex with YBX2 (By similarity). Interacts with RRP1B (PubMed:19710015)","family":"","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":[],"location":"Cytoplasm；Nucleus","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"翻译/核糖体；注释原文：Binds to the GM-CSF promoter.","function_evidence":"含同源推断，不能当该成员实测；ECO:0000250","categories":"翻译/核糖体"}};
